أولاً: المبادرة والإيمان الصادق
نشأ أبو بكر في مكة شريفاً من أشراف قريش، تاجراً أميناً، مألوفاً لقومه، عارِفاً بأنسابهم وأخبارهم، ولم يسجد لصنم في جاهليته قط عفةً وفطرة. ولما أكرم الله نبيه بالرسالة، كان أبو بكر أول من استجاب من الرجال دون تردد. قال رسول الله ﷺ في حقه شهادة سجلها التاريخ: «ما دعوت أحداً إلى الإسلام إلا كانت له عنه كبوة وتردد ونظر، إلا ما كان من أبي بكر؛ ما عكَم عنه حين ذكرته له وما تردد». ومضى من فوره داعياً إلى ربه، فأسلم على يديه خيرة السابقين الأولين: عثمان بن عفان، وعبد الرحمن بن عوف، والزبير بن العوام، وسعد بن أبي وقاص، وطلحة بن عبيد الله.

ثانياً: البذل المستميت ودفاعه عن النبي ﷺ بمكة
كان الصديق رضي الله عنه ذا ثروة وتجارة رابحة، فجعل ماله كله درعاً للدعوة الناشئة. وكان يشتري العبيد المستضعفين الذين يُسامون سوء العذاب في رمضاء مكة ليعتقهم لوجه الله، فأعتق بلال بن رباح وهو يصرخ تحت الصخور «أحدٌ أحد»، وأعتق عامر بن فهيرة، وأم عُبيس، وزنيرة، والنهدية وابنتها.
وعندما اشتد أذى المشركين حتى وثب عقبة بن أبي معيط على النبي ﷺ عند الكعبة وخنقه بثوبه خنقاً شديداً، أقبل أبو بكر مسرعاً حتى أخذ بمنكبي عقبة ودفعه عن النبي ﷺ وهو يبكي ويقول الكلمة القرآنية الخالدة: ﴿أَتَقْتُلُونَ رَجُلاً أَن يَقُولَ رَبِّيَ اللَّهُ وَقَدْ جَاءكُم بِالْبَيِّنَاتِ مِن رَّبِّكُمْ﴾، فتركوا النبي وانهالوا على أبي بكر ضرباً وركلاً حتى ما يُعرف وجهه من أنفه، ثم حُمل إلى داره بين الحياة والموت، فكان أول ما نطق به حين أفاق في آخر النهار: «ما فعل رسول الله ﷺ؟»، فأبى أن يطعم أو يشرب حتى رآه بعينيه مطمئناً.

ثالثاً: شرف الصديقية وصحبة الهجرة
لما أسري بالنبي ﷺ إلى بيت المقدس وعرج به إلى السماوات، جاء المشركون يسخرون ويقولون لأبي بكر: «هل لك في صاحبك يزعم أنه أُسري به الليلة إلى بيت المقدس؟»، فأجابهم بإيمان جلي: «أوقال ذلك؟ لئن كان قال ذلك لقد صدق، إني لأصدقه بأبعد من ذلك؛ أصدقه بخبر السماء غدوة وروحة»، فسمي من يومها «الصِّدِّيق».
ثم خصه الله بالشرف الذي لا يدانيه شرف حين اختاره النبي ﷺ ليكون رفيقه الوحيد في رحلة الهجرة المحفوفة بالأخطار، ودخلا غار ثور، ولما وقف فرسان قريش على شفير الغار، قال أبو بكر: «لو أن أحدهم نظر تحت قدميه لأبصرنا»، فثبته النبي ﷺ بالسكينة العظمى: «ما ظنك باثنين الله ثالثهما؟ لا تحزن إن الله معنا».

رابعاً: الجود الكامل في العسرة
في غزوة تبوك، حث رسول الله ﷺ المسلمين على الصدقة لتجهيز جيش العسرة، فجاء عمر بن الخطاب بنصف ماله وقال في نفسه: «اليوم أسبق أبا بكر إن سبقته يوماً»، ثم جاء أبو بكر بماله كله ولم يترك منه درهماً. فسأله رسول الله ﷺ: «يا أبا بكر، ما أبقيت لأهلك؟»، فأجاب برضا ويقين لا يبلغه بشر: «أبقيت لهم الله ورسوله». فبكى عمر وقال: «والله لا أسابقك إلى شيء أبداً».

خامساً: جبل الثبات يوم الفاجعة
حين قُبض رسول الله ﷺ، اضطرب المسلمون اضطراباً هائلاً وكادت عقولهم تذهب لهول المصيبة، ووقف عمر بن الخطاب رافعاً سيفه ينكر موته. فدخل أبو بكر وكشف عن وجه النبي ﷺ وقبّله بين عينيه وبكى وقال: «بأبي أنت وأمي، طبت حياً وميتاً، والله لا يجمع الله عليك موتتين أبداً».
ثم خرج وثبت كالجبل الأشم وخطب في الناس خطبته التي أعادت الأمة إلى رشدها: «ألا من كان يعبد محمداً فإن محمداً قد مات، ومن كان يعبد الله فإن الله حي لا يموت»، ثم قرأ: ﴿وَمَا مُحَمَّدٌ إِلاَّ رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ أَفَإِن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَى أَعْقَابِكُمْ﴾، فنشج الناس وبكوا وعلموا بالحق.

سادساً: الخلافة والزهد والرحيل
بويع بالخلافة فقام بأعباء الأمة بحزم وعدل، وأنفذ جيش أسامة بن زيد امتثالاً لأمر النبي ﷺ رغم اعتراض المعترضين، وحارب المرتدين وقال قولته التاريخية: «أينقص الدين وأنا حي؟ والله لو منعوني عقالاً كانوا يؤدونه إلى رسول الله لقاتلتهم عليه»، وجمع القرآن الكريم في الصحف لأول مرة.
وكان في خلافته يخرج إلى أطراف المدينة في الصباح الباكر ليخدم عجوزاً عمياء كفيفة، يقم بيتها ويحلب شاتها ويعجن خبزها دون أن يعلم من هي ولا تعلم من هو، حتى رآه عمر بن الخطاب فبكى وقال: «أتعبت الخلفاء بعدك يا أبا بكر».
توفي رضي الله عنه سنة 13 هـ وله من العمر 63 عاماً، ودُفن إلى جانب خليله ورسوله محمد ﷺ في حجرة عائشة، لتتصل صحبتهما في الدنيا وفي البرزخ وفي مقعد صدق عند مليك مقتدر."""
