أولاً: نبذة وإسلامه المبارك
نشأ عمر في مكة رجلاً مهيباً، قوي الشكيمة، من أشراف قريش وسفرائها في الجاهلية. وكان في أول أمره شديد العداوة للمسلمين، حتى دعا النبي ﷺ دعوته الخالدة: «اللهم أعز الإسلام بأحب هذين الرجلين إليك: بأبي جهل أو بعمر بن الخطاب»، فكان أحبهما إلى الله عمر.
أسلم رضي الله عنه في ذي الحجة من السنة السادسة للبعثة، وكان إسلامه فتحاً مبيناً ونصرة للمستضعفين؛ قال عبد الله بن مسعود رضي الله عنه: «ما زلنا أعزة منذ أسلم عمر؛ ولقد رأيتنا وما نستطيع أن نصلي بالبيت حتى أسلم عمر، فقاتلهم حتى صلّينا».

ثانياً: موافقات الوحي والمكانة النبوية
تميز الفاروق بعمق الفراسة ونقاء البصيرة، حتى وافقه القرآن الكريم في عدة مواضع؛ منها قوله للنبي ﷺ: «لو اتخذنا من مقام إبراهيم مصلى» فنزلت ﴿وَاتَّخِذُوا مِن مَّقَامِ إِبْرَاهِيمَ مُصَلًّى﴾، وفي آية حجاب أمهات المؤمنين، وفي شأن أسرى بدر.
وقال النبي ﷺ في مناقبه في الصحيحين: «لقد كان فيما قبلكم من الأمم ناسٌ محدَّثون، فإن يكن في أمتي أحدٌ فإنه عمر»، وقال ﷺ: «والذي نفسي بيده، ما لقيك الشيطان قط سالكاً فجاً إلا سلك فجاً غير فجك».

ثالثاً: الهجرة والمشاهد والجهاد في سبيل الله
شهد عمر مع رسول الله ﷺ المشاهد كلها، فكان نعم الوزير والناصح لأبي بكر وللنبي ﷺ. في بدر ثبت وبارز، وفي أحد رد على أبي سفيان نداءه حين نادى أفيكم محمد؟ أفيكم ابن أبي قحافة؟ أفيكم عمر؟ فصاح عمر: «كذبت يا عدو الله، قد أبقى الله لك ما يخزيك!». وفي الحديبية ناقش غيرةً على دينه، ثم أدرك حكمة النبي ﷺ وسكينة الفتح، وظل يتصدق ويصوم تكفيراً لشدته تلك. وفي تبوك تصدق بنصف ماله كله.

رابعاً: خلافته الراشدة وعدله الأسطوري
تولى الخلافة بعد وفاة الصديق سنة 13 هـ، فدانت له ممالك كسرى وقيصر، وفُتحت في عهده بلاد الشام والعراق وفارس ومصر وبيت المقدس؛ حيث دخل القدس بثوبه المرقع وكتب لأهلها «العهدة العمرية» أماناً لكنائسهم وأنفسهم.
وكان يطوف بالليل في سكك المدينة (العَسَس) يتفقد الجياع والفقراء بنفسه، وحمل كيس الدقيق على ظهره لامرأة جائعة وأيتامها، ورفض أن يأكل السمن في عام الرمادة وقال: «كيف يعنيني شأن الرعية إذا لم يمسني ما مسهم؟ قرقري أو لا تقرقري، فوالله لا تشبعين حتى يشبع صغار المسلمين».

خامساً: استشهاده ووفاته
كان يدعو دائماً: «اللهم ارزقني شهادة في سبيلك، واجعل موتي في بلد رسولك»، فاستجاب الله دعاءه؛ فبينما هو قائم يصلي بالمسلمين صلاة الفجر في المسجد النبوي، غدر به أبو لؤلؤة المجوسي وطعنه ست طعنات بخنجر مسموم. وحين حُمل إلى بيته وسأل عمن طعنه وقيل له غلام المغيرة بن شعبة، قال: «الحمد لله الذي لم يجعل ميتتي بيد رجل سجد لله سجدة واحدة».
توفي رضي الله عنه في أواخر ذي الحجة سنة 23 هـ، ودفن بجوار النبي ﷺ وأبي بكر الصديق.

ماذا نتعلم من سيرة الفاروق؟
1. أن القوة والصلابة في الحق لا قيمة لها إلا إذا زانها العدل والرحمة بالضعفاء والمساكين.
2. عظمة المحاسبة الذاتية للمسؤول؛ فكان يقول: «حاسبوا أنفسكم قبل أن تحاسبوا».
3. التواضع في أوج النصر والتمكين؛ دخل القدس فاتحاً خاضعاً متذللاً لله.

