      "day": """هو عثمان بن عفان بن أبي العاص بن أمية الأموي القرشي، كنيته «أبو عبد الله» و«أبو عمرو»، ولُقب بـ «ذي النورين»؛ لأنه تزوج ابنتي رسول الله ﷺ رقية ثم أم كلثوم، ولم يُعلم أحد في التاريخ تزوّج ابنتي نبي غيره.

أولاً: نبذة وإسلامه المبارك
كان عثمان في الجاهلية من كرام قريش ورجالها ذوي المكانة والثروة والحياء العظيم، ولم يشرب خمراً قط ولا سجد لوثن. أسلم في أول أيام الدعوة حين عرض عليه أبو بكر الصديق الإسلام، فبادر دون تردد وكان من السابقين الأولين.
أوذي في الله بمكة فصبر، وهاجر مع زوجته رقية إلى أرض الحبشة في الهجرة الأولى فراراً بدينهما، فكان أول بيت هاجر في سبيل الله بعد لوط وإبراهيم عليهما السلام، ثم هاجر الهجرة الثانية إلى المدينة المنورة.

ثانياً: البذل العظيم والجود الذي لا نظير له
عندما قدم المسلمون المدينة وكان ماء الشرب شحيحاً يملكه يهودي يبيع القربة بثمن غالٍ، قال النبي ﷺ: «من يشتري بئر رُومة فيجعل دلوه فيها مع دلاء المسلمين بخير له منها في الجنة؟»، فاشتراها عثمان من ماله وجعلها وقفاً مجانياً للمسلمين إلى يوم القيامة.
وفي غزوة تبوك (جيش العسرة)، جهز عثمان ثلث الجيش بنفقته الخاصة؛ فجاء بتسعمائة وخمسين بعيراً وخمسين فرساً، وصب في حجر النبي ﷺ ألف دينار ذهبي، فجعل النبي ﷺ يقلبها مسروراً ويقول: «ما ضر عثمان ما عمل بعد اليوم، ما ضر عثمان ما عمل بعد اليوم!».

ثالثاً: مكانته وفضيلة حيائه الثابتة
شهد له النبي ﷺ بالجنة والشهادة، وكانت بيعة الرضوان في الحديبية شرفاً لعثمان؛ إذ أرسله النبي ﷺ مفاوضاً لقريش، ولما شاع أنه قُتل بايع النبي الصحابة تحت الشجرة، وقال واضعاً يده اليمنى على اليسرى: «هذه يد عثمان»، فبايع عنه ﷺ.
وثبت في صحيح مسلم عن عائشة رضي الله عنها أن النبي ﷺ جمع ثيابه لما دخل عثمان وقال: «ألا أستحي من رجل تستحي منه الملائكة؟!».

رابعاً: خلافته العظمى وجمع المصحف الشريف
بويع بالخلافة بعد استشهاد عمر بن الخطاب سنة 23 هـ، فاتسعت رقعة الدولة اتساعاً هائلاً وفُتحت أرمينيا وأذربيجان وسجستان وكرمان وشمال إفريقيا، وأنشأ أول أسطول بحري إسلامي حمى به شواطئ المسلمين.
وكان أعظم أعماله التي بقيت للأمة إلى يوم القيامة: «جمع القرآن الكريم في مصحف واحد»؛ إذ خشي حذيفة بن اليمان من اختلاف الناس في قراءة القرآن بالأمصار، فأمر عثمان بتجريد المصاحف ونسخها بحرف قريش، وتوزيعها على الأمصار وحرق ما عداها، فوحد الأمة على كلمة واحدة.

خامساً: استشهاده صابراً محتسباً
نشبت الفتنة وحاصره المتمردون في داره أربعين يوماً ومنعوا عنه الماء، وعرض عليه الصحابة كعلي والحسن وابن عمر القتال دونه، فأبى وأمرهم بالانصراف قائلاً: «لا أكون أول من يهريق دماً في أمة محمد».
واقتحم عليه المعتدون داره وهو يتلو القرآن الكريم صائماً، فضربوه بسيوفهم فقطعوا يد زوجته نائلة واستشهد رضي الله عنه ودمه يسيل على المصحف عند قوله تعالى: ﴿فَسَيَكْفِيكَهُمُ اللَّهُ وَهُوَ السَّمِيعُ الْعَلِيمُ﴾ في ذي الحجة سنة 35 هـ وله من العمر 82 عاماً.

ماذا نتعلم من سيرة ذي النورين؟
1. بذل المال واستثماره في المشاريع الوقفية التي يستمر أجرها بعد الموت.
2. خُلق الحياء وعفته في السر والعلانية؛ فهو شعبة عظيمة من الإيمان.
3. التضحية بالنفس والمصلحة الفردية في سبيل حقن دماء المسلمين ووحدة صفهم.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب فضائل الصحابة، باب مناقب عثمان بن عفان (حديث 3696، 3698، 3699)، وكتاب فضائل القرآن (حديث 4987).
• صحيح مسلم: كتاب فضائل الصحابة، باب من فضائل عثمان بن عفان (حديث 2401، 2402).
• البداية والنهاية لابن كثير (الجزء السابع، أحداث الفتنة ومقتل عثمان)."""
