      "biography": "علي بن أبي طالب بن عبد المطلب الهاشمي القرشي، كرم الله وجهه، أول فدائي في الإسلام، حيدرة الكرار وفاتح خيبر.",
      "battles": ["غزوة بدر الكبرى","غزوة أحد","غزوة الخندق","غزوة بني قريظة","صلح الحديبية","غزوة خيبر","فتح مكة","غزوة حنين"],
