      "additionalInfo": "افتدا النبي ﷺ بمبيته في فراشه ليلة الهجرة، وتزوج سيدة نساء العالمين فاطمة الزهراء.",
      "day": """هو علي بن أبي طالب بن عبد المطلب الهاشمي القرشي، ابن عم رسول الله ﷺ، كنيته «أبو الحسن» و«أبو تراب»؛ لقب أحبه إلى قلبه كنّاه به النبي ﷺ حين وجده نائماً في المسجد وسقط رداؤه وأصابه التراب فجعل يمسحه ويقول: «قم يا أبا تراب، قم يا أبا تراب».

أولاً: نشأته وإسلامه كأول فدائي
نشأ علي في حجر النبي ﷺ ورعايته رداً لجميل عمه أبي طالب، فتربى على النقاء والتوحيد الخالص ولم يسجد لصنم قط. ولما نزل الوحي كان أول من أسلم من الصبيان وله من العمر نحو عشر سنوات.
وفي ليلة الهجرة المباركة، ضرب علي أروع أمثلة الفداء والتضحية حين أمره النبي ﷺ أن يبيت في فراشه ويتسجى ببرده الحضرمي الأخضر ليوهم المشركين المحاصرين للدار أن النبي ما زال نائماً، وظل في مكة ثلاثة أيام بعد خروج النبي ليرد الأمانات والودائع التي كانت عند النبي لأصحابها.

ثانياً: مصاهرته لبيت النبوة وبطولته المشهودة
زوجه النبي ﷺ من أحب بناته إليه سيدة نساء أهل الجنة فاطمة الزهراء رضي الله عنها، فولدت له الحسن والحسين سيدي شباب أهل الجنة والمحسن وزينب وأم كلثوم.
وكان علي رأس فرسان المسلمين في المشاهد؛ ففي بدر افتتح القتال ببراعة وقتل الوليد بن عتبة وشارك في قتل صناديد قريش، وفي أحد ثبت ثبات الجبال يدافع عن النبي ﷺ حتى جُرح، وفي الخندق برز لفارس قريش الذي لا يُقهر عمرو بن عبد ود العامري فصرعه علي وكبّر المسلمون تكبيراً هز جنبات الخندق.

ثالثاً: فتح خيبر والمنزلة العظمى
في غزوة خيبر استعصت الحصون أياماً، فقال النبي ﷺ قوله الخالد: «لأعطين الراية غداً رجلاً يحب الله ورسوله، ويحبه الله ورسوله، يفتح الله على يديه». فبات الصحابة يرجون أن يُدعى كل منهم إليها، فلما أصبحوا قال: «أين علي بن أبي طالب؟»، فقيل هو يشتكي عينيه، فبصق ﷺ في عينيه ودعا له فبرأ كأن لم يكن به وجع، وأعطاه الراية ففتح الله الحصون على يديه وقتل مرحب فارس يهود في مبارزة تاريخية مشهودة.
ولما استخلفه النبي ﷺ على أهله في المدينة في غزوة تبوك، قال علي: «أتخلفني في النساء والصبيان؟»، فقال له النبي مطمئناً: «أما ترضى أن تكون مني بمنزلة هارون من موسى، إلا أنه لا نبي بعدي؟».

رابعاً: خلافته وزهده وفقهه العظيم
بويع بالخلافة بعد استشهاد عثمان سنة 35 هـ في أوقات عصيبة من الفتن، فسار بالعدل والزهد العظيم، وكان يقسم بيت المال بالعدل ولا يستأثر لنفسه بدرهم، ويخرج إلى السوق بالكوفة وبيده الدرة يأمر الناس بتقوى الله والصدق في الكيل والميزان.
وكان قمة في العلم والقضاء؛ قال فيه عمر بن الخطاب: «أقضانا علي»، وكان الصحابة يرجعون إليه في معضلات المسائل وفتاوى الأحكام.

خامساً: استشهاده ووفاته
في صبيحة يوم الجمعة السابع عشر من شهر رمضان المبارك سنة 40 هـ، بينما كان خارجاً إلى صلاة الفجر في مسجد الكوفة ينادي الناس «الصلاة الصلاة»، وثب عليه الشقي عبد الرحمن بن ملجم الخارجي بسيف مسموم وضربه على هامته، ففاضت روحه الطاهرة شهيداً راضياً مرضياً وله من العمر نحو 63 عاماً.

ماذا نتعلم من سيرة أمير المؤمنين علي؟
1. الشجاعة المطلقة في نصرة الحق والاستعداد للتضحية بالنفس دون تردد.
2. العدل والزهد الحقيقي في شؤون الحكم والإدارة والمال العام.
3. الحرص على العلم والفقه وتوظيف الذكاء والحكمة في حل المعضلات.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب فضائل الصحابة، باب مناقب علي بن أبي طالب (حديث 3701، 3706)، وكتاب المغازي (حديث 4416).
• صحيح مسلم: كتاب فضائل الصحابة، باب من فضائل علي بن أبي طالب (حديث 2404، 2405، 2406).
• سيرة ابن هشام، وتاريخ الطبري (أحداث خلافة علي ومقتله)."""
