      "day": """هو طلحة بن عبيد الله بن عثمان بن عمرو بن كعب التيمي القرشي، كنيته «أبو محمد»، لُقب بـ «طلحة الخير» و«طلحة الفياض» و«الشهيد الحي»؛ لمواقفه العظيمة في البذل والشجاعة.

أولاً: نبذة وإسلامه المبكر
كان طلحة تاجراً نبيلاً خرج إلى بصرى الشام في تجارة، فالتقى راهباً بشره بمبعث أحمد بمكة، فعاد مسرعاً إلى مكة فلقي أبا بكر وأسلم على يديه فوراً، فكان أحد الثمانية السابقين إلى الإسلام.
أوذي في الله بمكة، فقرنه نوفل بن خويلد مع أبي بكر في حبل واحد ليعذبوهما، فسميا لذلك «القرينين»، فثبتا على دين الله ولم يرتدا.

ثانياً: بطولة أحد العظمى (الشهيد الحي)
كان يوم أحد يوم طلحة بحق؛ فعندما دارت الدائرة على المسلمين وانكشف الناس عن النبي ﷺ، لم يبقَ يذود عن النبي إلا قلة نادرة ثبت في مقدمتهم طلحة بن عبيد الله.
أحاط المشركون برسول الله ﷺ وأرادوا قتله، فجعل طلحة يقاتل كأنه كتيبة بأسرها؛ يرمي بالنبل، ويضرب بالسيف، ويتلقى السهام والرماح بجسده دون النبي ﷺ، حتى شُلت يده التي وقى بها وجه رسول الله من سهم صائب، وأصيب يومها ببضع وسبعين ضربة وطعنة، ثم حمل النبي ﷺ على ظهره وصعد به إلى صخرة الجبل حين أثقله الجهد.
فقال النبي ﷺ حينئذ كلمته المشهورة: «أوجب طلحة» (أي وجبت له الجنة)، وقال: «من سره أن ينظر إلى شهيد يمشي على وجه الأرض فلينظر إلى طلحة بن عبيد الله». وكان أبو بكر إذا ذُكر يوم أحد قال: «ذلك اليوم كله كان لطلحة».

ثالثاً: جوده العظيم وفيضه
كان طلحة من أثرى الصحابة وأكثرهم سخاءً على الإطلاق؛ باع أرضاً له ذات يوم بسبعمائة ألف درهم فبات ليلته قلقاً مهموماً حتى فرقها كلها في فقراء المهاجرين والأنصار قبل أن يصبح.
وكان يتكفل بأيتام بني تيم ويزوج أراملهم ويقضي ديونهم، فسمّاه النبي ﷺ «طلحة الخير» و«طلحة الجود» و«طلحة الفياض».

رابعاً: وفاته ونهاية حياته
اعتزل الفتنة بعد أن شارك في بدايتها في موقعة الجمل سنة 36 هـ نادماً على ما جرى، فأصابه سهم غادر أودى بحياته، وله من العمر نحو 64 عاماً. ودخل علي بن أبي طالب فرآه صريعاً فمسح التراب عن وجهه وبكى وقال: «يعز عليّ أبا محمد أن أراك مجندلاً تحت نجوم السماء، إلى الله أشكوا عُجري وبُجري!».

ماذا نتعلم من سيرة طلحة بن عبيد الله؟
1. الفداء والوفاء للقيادة والمبدأ؛ جاد بيده وجسده ليبقى رسول الله ﷺ حياً.
2. أن بركة المال تتضاعف بالإنفاق في وجوه الخير والصدقة الخفية.
3. التوبة والرجوع إلى الحق فور تبيّنه مهما بلغت الظروف والتحديات.

المصادر والمراجع المعتمدة:
