• سنن الترمذي: كتاب المناقب، باب مناقب طلحة بن عبيد الله (حديث 3738، 3742).
• سيرة ابن هشام، وسير أعلام النبلاء للذهبي (ترجمة طلحة بن عبيد الله)."""
