      "day": """هو الزبير بن العوام بن خويلد بن أسد الأسدي القرشي، كنيته «أبو عبد الله»، ابن عمة رسول الله ﷺ صفية بنت عبد المطلب، وحواريّ النبي ﷺ، وأحد الستة أصحاب الشورى.

أولاً: نبذة وإسلامه وأول سيف في الإسلام
أسلم الزبير بمكة وهو فتى يافع لا يتجاوز عمره ست عشرة سنة، فكان من السابقين الأولين.
وذات يوم في مكة سرت إشاعة أن النبي ﷺ قد أُسر أو قُتل، فخرج الزبير مصلتاً سيفه يشق صفوف مكة باحثاً عن النبي وعمره إذ ذاك قليل، فلقيه النبي ﷺ في أعلى مكة فقال: «ما لك يا زبير؟»، قال: «سمعت أنك أُخذت»، قال: «فما كنت صانعاً؟»، قال: «كنت أضرب بسيفي من أخذك!»، فدعا له النبي ﷺ ولسيفه، فكان أول سيف سُلّ في الإسلام.

ثانياً: بطولاته وثباته في المعارك
شهد الزبير بدراً وأحداً والمشاهد كلها، وفي يوم بدر نزل بفرسه متوشحاً بعمامة صفراء، فنزل جبريل والملائكة على سيماء الزبير وعليهم عمائم صُفر، فقال النبي ﷺ: «إن الملائكة نزلت على سيماء الزبير».
وفي غزوة الخندق، لما حاصر الأحزاب المدينة وخشي النبي من غدر بني قريظة، قال: «من يأتينا بخبر القوم؟»، فقال الزبير: «أنا»، ثم قالها ثانية فقال الزبير: «أنا»، ثم قالها ثالثة فقال الزبير: «أنا»، فقال النبي ﷺ كلمته الخالدة: «لكل نبي حواريّ، وحواريّ الزبير»، وجمع له أبويه فقال: «فداك أبي وأمي».
وفي معركة اليرموك شق صفوف الروم مرتين بمفرده حتى خرج من الجانب الآخر وعاد وجراحه تثعب دماً، مظهراً شجاعة أذهلت جيوش العالم.

ثالثاً: صدقه وزهده وأمانته
كان الزبير تاجراً ثرياً، لكنه لم يكن يدخر ماله؛ بل كان يبذله في سبيل الله وإعانة المحتاجين. وكان الصحابة يستودعونه أموالهم وأيتامهم لفرط أمانته، فكان يجعل الودائع ديوناً على نفسه خشية ضياعها ليضمن ردها لأهلها.

رابعاً: استشهاده ووفاته
خرج من موقعة الجمل سنة 36 هـ منصرفاً عازماً على ترك القتال بعد أن ذكّره علي بن أبي طالب بحديث للنبي ﷺ، فتبعه رجل يُدعى ابن جرموز وغدر به وهو يصلي بوادي السباع فقتله. وجاء القاتل برأس الزبير وسيفه إلى علي يرجو الجائزة، فبكى علي وقال: «بشر قاتل ابن صفية بالنار»، ثم تناول سيف الزبير وقبله وقال: «سيفٌ طالما واللهِ جلا الكربَ عن وجه رسول الله ﷺ!».

ماذا نتعلم من سيرة حواري الرسول؟
1. الشجاعة والمبادرة الفدائية في أصعب المواقف والأزمات.
2. عظمة الأمانة والحرص التام على أموال الناس وحقوقهم.
3. التراجع الفوري عن الخطأ عند تذكر الحق وسنة النبي ﷺ.

المصادر والمراجع المعتمدة:
