      "day": """هو سعد بن مالك بن وهيب الزهري القرشي، كنيته «أبو إسحاق»، وخال رسول الله ﷺ؛ لأن أم النبي آمنة بنت وهب كانت زهرية، وكان النبي يفخر به ويقول حين يراه مقبلاً: «هذا خالي، فليرني امرؤٌ خاله!».

أولاً: إسلامه وبره بأمه
أسلم سعد وعمره سبع عشرة سنة، وكان ثالث أو سابع رجل أسلم في الإسلام.
ولما علمت أمه بإسلامه حلفت ألا تأكل ولا تشرب ولا تستظل حتى يرجع عن دينه وتموت فيُعيّر بها، فظلت أياماً حتى كادت تهلك، فجاءها سعد بثبات إيماني عميق وقال: «يا أماه، لو كانت لكِ مائة نفس فخرجت نفساً نفساً ما تركت ديني هذا لشيء؛ فكلي إن شئتِ أو لا تأكلي»، فلما رأت ثباته أكلت، وأنزل الله تعالى في شأنه: ﴿وَإِن جَاهَدَاكَ عَلَى أَن تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا﴾.

ثانياً: أول سهم في الإسلام وموقف يوم أحد
كان سعد أول من رمى بسهم في سبيل الله في سرية سيف البحر، وشهد المشاهد كلها.
وفي يوم أحد، وقف يرمي السهام والنبي ﷺ يلقي له السهام بنفسه ويقول: «ارمِ سعد، فداك أبي وأمي»، ولم يجمع النبي ﷺ أبويه لأحد في فداء إلا لسعد بن أبي وقاص والزبير بن العوام.
ودعا له النبي ﷺ بدعوة صارت علامة له في حياته: «اللهم سدد رميته، وأجب دعوته»، فكان لا يرمي سهماً إلا أصاب، ولا يدعو دعاءً إلا استُجيب له من فوره؛ وكان الصحابة يتقون دعاء سعد أشد الاتقاء.

ثالثاً: قيادة القادسية وفتح العراق والمدائن
اختاره عمر بن الخطاب لقيادة جيش المسلمين لفتح العراق وإسقاط دولة الأكاسرة سنة 15 هـ، فقاد معركة القادسية الخالدة بحنكة عسكرية باهرة وهو مريض عاجز عن الركوب يُدير المعركة من قصره، حتى هزم جيش الفرس الأسطوري وقُتل رستم.
ثم سار حتى دخل المدائن (عاصمة كسرى)، وصلى في إيوان كسرى صلاة الفتح ثماني ركعات، ونفذ نبوءة النبي ﷺ باقتسام كنوز كسرى وتيجانه، وأسس مدينة الكوفة لتكون معسكراً وحاضرة للمسلمين.

رابعاً: وفاته رضي الله عنه
كان آخر العشرة المبشرين بالجنة موتاً؛ عاش حتى سنة 55 هـ، وتوفي في قصره بالعقيق وحُمل على أعناق الرجال إلى المدينة ودُفن بالبقيع، وأوصى أن يُكفّن في جبة صوف بالية كانت عنده وقال: «كفّنوني بها، فإني لقيتُ بها المشركين يوم بدر، وإنما كنت أخبؤها لهذا اليوم!».

ماذا نتعلم من سيرة سعد بن أبي وقاص؟
1. تقديم محبة الله ورسوله على الوالدين مع استمرار البر والإحسان الدنيوي لهما.
2. اليقين في استجابة الدعاء وأثر الإخلاص وطيب المطعم في إجابة النداء.
3. التخطيط العسكري الصارم وإدارة المعارك المصيرية بالحكمة والشجاعة.

المصادر والمراجع المعتمدة:
