أولاً: إسلامه وعزة نفسه النادرة
أسلم عبد الرحمن قديماً على يد أبي بكر الصديق قبل دخول دار الأرقم، وهاجر إلى الحبشة الهجرتين ثم هاجر إلى المدينة المنورة.
ولما آخى النبي ﷺ بينه وبين سعد بن الربيع الأنصاري، قال له سعد: «أنا أكثر الأنصار مالاً، فأقسم مالي نصفين، ولي زوجتان فانظر أيهما تعجبك أطلقها وتتزوجها»، فرفض عبد الرحمن بعزة نفس مؤمنة وشهامة نادرة وقال كلمته التي صارت دستوراً في العمل: «بارك الله لك في أهلك ومالك، ولكن دلّوني على السوق!».

ثانياً: بركة التجارة وسر الثراء الحلال
ذهب إلى سوق قينقاع وبدأ يشتري ويبيع الأقط والسمن برأس مال يسير حتى ربح، ثم توسعت تجارته بصورة مذهلة لصدقه وأمانته حتى قال: «لقد رأيتني لو رفعتُ حجراً لرجوتُ أن أجد تحته ذهباً أو فضة!».
ولم يكن ثراؤه للكنز والتفاخر، بل كان سحابة جود على المسلمين؛ أعتق مئات العبيد، وتصدق بنصف ماله مرة، ثم بأربعين ألف دينار مرة أخرى، وحمل على خمسمائة فرس وخمسمائة راحلة في سبيل الله.
وحين دخلت قافلته المدينة ذات يوم وكانت سبعمائة راحلة محملة بالبر والدقيق ارتجت لها المدينة، فقال: «أشهدكم أنها كلها وما عليها صدقة لفقراء المسلمين وأيتامهم!».

ثالثاً: شرف الصلاة بالنبي ﷺ والجهاد
شهد بدراً والمشاهد كلها، وأصيب يوم أحد بأكثر من عشرين جراحة، ورُمي في رجله فعرج منها وسقطت ثنيتاه.
وفي غزوة تبوك، حان وقت صلاة الفجر والنبي ﷺ غائب يتوضأ، فقدم الصحابة عبد الرحمن بن عوف فصلى بهم، وأدرك النبي ﷺ الركعة الثانية فصلى مأموماً خلف عبد الرحمن بن عوف، فلما سلم عبد الرحمن قام النبي فأتم ركعته وقال: «أحسنتم وأصبتم». ولم يصلِّ النبي خلف أحد من أمته إلا خلف أبي بكر وعبد الرحمن بن عوف.

رابعاً: وفاته رضي الله عنه
توفي سنة 32 هـ بالمدينة المنورة وله من العمر نحو 75 عاماً، وصلى عليه عثمان بن عفان وحمل جنازته سعد بن أبي وقاص ودُفن بالبقيع.

ماذا نتعلم من سيرة عبد الرحمن بن عوف؟
1. عزة النفس والاعتماد على الكسب الحلال والعمل اليدوي والتجاري.
2. أن المال في يد الصالحين وسيلة كبرى لنصرة الدين وكفاية الفقراء وسد حاجات الأمة.
3. التواضع الشديد مع الغنى؛ كان يجلس بين غلمانه فلا يُميز السيد من خادمه.

المصادر والمراجع المعتمدة:
