أولاً: نبذة وإسلامه المبكر
كان أبو عبيدة من السابقين الأولين؛ أسلم في اليوم التالي لإسلام أبي بكر الصديق قبل دخول دار الأرقم، وهاجر إلى الحبشة الهجرة الثانية ثم هاجر إلى المدينة المنورة.
وكان رضي الله عنه رجلاً طوالاً، نحيف الوجه، خفيف اللحية، أبهى الناس طَلعة، وألينهم جانباً، وأشدهم شجاعة إذا اشتد البأس.

ثانياً: أمانة الأمة والبطولة في أحد
ثبت في الصحيحين أن أهل نجران لما جاؤوا يطلبون رجلاً أميناً يقضي بينهم ويقبض جزيتهم، قال رسول الله ﷺ: «لأبعثنّ إليكم رجلاً أميناً، حق أمين، حق أمين»، فاستشرف لها الصحابة رجاء هذا الشرف، فبعث النبي ﷺ أبا عبيدة بن الجراح وقال: «إن لكل أمة أميناً، وإن أميننا أيتها الأمة: أبو عبيدة بن الجراح».
وفي غزوة أحد، لما رُمي النبي ﷺ ونشبت حلقتان من حلق المغفر في وجنته الشريفة، أقبل أبو عبيدة يسعى كأنه طائر، وألح على أبي بكر أن يدعه ينزعهما، فأخذ الحلقة الأولى بثنيته فجذبها جذباً رفيقاً حتى نزعها وسقطت ثنيته، ثم أخذ الحلقة الأخرى بثنيته الأخرى فنترها فسقطت ثنيته الثانية، فصار أهتم، وكان هتمه زينة في وجهه.

ثالثاً: قيادة جيوش الشام وفتح اليرموك
جعله عمر بن الخطاب أميراً عاماً على جيوش الشام وقائداً للفتوحات، فقاد معركة اليرموك الخالدة بحنكة وتواضع؛ حيث نزل قرار عزله لخالد وتعيينه مكانه وهو في قلب المعركة فكتم الخبر حتى تم النصر للمسلمين كي لا يزعزع ثقة الجنود، ثم أعلن القرار بأدب جم وتقدير لخالد، فكان نعم القائد ونعم الأخ.
وفُتحت على يديه دمشق وحمص وحماة وحلب وسائر بلاد الشام، ودخل بيت المقدس مع عمر بن الخطاب.

رابعاً: زهده المبكي ورحيله في طاعون عمواس
دخل عليه عمر بن الخطاب في منزله بحمص وهو أمير الشام، فلم يجد في بيته سوى سيفه وقوسه ورحله وجلدة شاة وإناء يشرب منه وكسرات خبز يابسة، فبكى عمر وقال: «غيرتنا الدنيا كلنا غيرك يا أبا عبيدة!»، فقال له أبو عبيدة مبتسماً: «يا أمير المؤمنين، إنما هي دار بلاغ، وهؤلاء يبلغننا المقيل».
وفي سنة 18 هـ أصاب الشام طاعون عمواس، وأبى أبو عبيدة أن يخرج ويترك جنوده ورعيته، فطعن وتوفي رضي الله عنه وله من العمر 58 عاماً، وصلى عليه معاذ بن جبل ودُفن في غور الأردن.

ماذا نتعلم من سيرة أمين الأمة؟
1. الأمانة المطلقة في حفظ الدين والمال وحقوق المسلمين.
2. الزهد الحقيقي ونكران الذات؛ تنازل عن الصدارة ووضع مصلحة الجيش فوق كل اعتبار.
3. الثبات والوفاء مع الجنود والرعية في أوقات الأوبئة والشدائد.

