      "additionalInfo": "قال عنه النبي ﷺ: «سيد الشهداء حمزة بن عبد المطلب، ورجل قام إلى إمام جائر فأمره ونهاه فقتله».",
      "day": """هو حمزة بن عبد المطلب بن هاشم الهاشمي القرشي، كنيته «أبو عمارة» و«أبو يعلى»، عم رسول الله ﷺ وأخوه من الرضاعة، لقبه النبي بـ «أسد الله وأسد رسوله» و«سيد الشهداء».

أولاً: نبذة وإسلامه الحاسم بمكة
كان حمزة فتى قريش شجاعةً وعزةً وفروسية، وكان يعشق الصيد والقنص. وفي السنة السادسة للبعثة، عاد من قنصه متوشحاً قوسه، فأخبرته مولاة لعبد الله بن جدعان أن أبا جهل سبّ ابن أخيه محمداً ﷺ وآذاه ونال منه عند الصفا، فاستشاط حمزة غضباً ومضى نحو الكعبة فوجد أبا جهل جالساً في نادي قريش، فوقف عليه ورفع قوسه وشج به رأس أبي جهل شجة منكرة، ثم قال كلمته التاريخية التي زلزلت بطحاء مكة: «أتشتمه وأنا على دينه، أقول ما يقول؟! فردّ ذلك عليّ إن استطعت!».
وكان إسلام حمزة عزاً هائلاً للدعوة، فكفت قريش عن كثير من أذاها للنبي ﷺ لعلمها ببأس حمزة ومنعته.

ثانياً: بطولته في المشاهد وقيادة أول لواء
عقد له النبي ﷺ أول لواء في الإسلام في سرية سيف البحر لملاقاة قريش.
وفي يوم بدر الكبرى، برز حمزة كأنه الصاعقة يرتدي ريشة نعامة في صدره ليعرف بها، وبادر بمبارزة شيبة بن ربيعة فصرعه، وقتل من صناديد قريش وأبطالهم ما أذهل المشركين، وكان رجل المعركة الأول حتى سأل أمية بن خلف بعد الأسر: «من الرجل المعلم بريشة نعامة في صدره؟»، فقيل: «حمزة بن عبد المطلب»، فقال أمية: «ذاك الذي فعل بنا الأفاعيل!».

ثالثاً: استشهاده المفجع يوم أحد
في شوال سنة 3 هـ في غزوة أحد، كان حمزة يصول ويجول بسيفين وهو يقول: «أنا أسد الله وأسد رسوله»، فكمن له وحشي بن حرب (وكان عبداً حبشياً وُعد بالعتق إن قتل حمزة)، فلما اقترب حمزة وهو يقاتل أحد المشركين، هز وحشي حربته وزرقها فأصابته في ثنته فخرجت من بين وركيه، فوقع أسد الله شهيداً.
ولم يكتفِ المشركون بقتله، بل مثلت به هند بنت عتبة وبقرت بطنه. ولما وقف النبي ﷺ على جثمان عمه بكى بكاءً شديداً وقال: «رحمك الله يا عم، فلقد كنت وصُولاً للرحم، فعُولاً للخيرات، ولولا أن تحزن صفية لتركته حتى يحشره الله من بطون السباع وحواصل الطير»، ثم كفنه ببردة إذا غطت رأسه بدت قدماه، وقال: «سيد الشهداء عند الله يوم القيامة حمزة بن عبد المطلب».

ماذا نتعلم من سيرة أسد الله حمزة؟
1. توظيف القوة والشجاعة والهيبة لنصرة الحق وحماية المستضعفين.
2. أن الشهادة في سبيل الله اصطفاء ومقام عظيم يعوض الله به الصابرين.
3. الوفاء لصلة الرحم والوقوف مع أصحاب الدعوات النبيلة في المحن.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب المغازي، باب قتل حمزة بن عبد المطلب (حديث 4072).
• صحيح مسلم: كتاب الجهاد والسير، باب غزوة أحد (حديث 1799).
• سيرة ابن هشام، والاستيعاب لابن عبد البر (ترجمة حمزة بن عبد المطلب)."""
    },

    "جعفر بن أبي طالب": {
