      "biography": "جعفر بن أبي طالب بن عبد المطلب الهاشمي القرشي، أخو علي بن أبي طالب، المهاجر الصادق الذي حاور النجاشي فأبكى الحاضرين، واستشهد حاملاً الراية بمؤتة.",
      "battles": ["غزوة مؤتة"],
      "attributes": ["ذو الجناحين","جعفر الطيار","أبو المساكين","سفير الحبشة"],
      "additionalInfo": "قال له النبي ﷺ: «أشبهت خَلقي وخُلقي»، وعوضه الله عن يديه جناحين يطير بهما في الجنة مع الملائكة.",
      "day": """هو جعفر بن أبي طالب بن عبد المطلب الهاشمي القرشي، كنيته «أبو عبد الله»، ابن عم رسول الله ﷺ، وأخو علي الأكبر منه بعشر سنين، لقبه النبي ﷺ بـ «جعفر الطيار» و«ذي الجناحين»، وكنّاه أبو هريرة بـ «أبي المساكين» لفرط إحسانه للفقراء.

أولاً: إسلامه ومناظرة الحبشة التاريخية
أسلم جعفر قديماً بعد إسلام أخيه علي بقليل، ولما اشتد عذاب قريش قاد جعفر بن أبي طالب وزوجته أسماء بنت عميس وفد المهاجرين إلى أرض الحبشة.
وهناك أرسلت قريش عمرو بن العاص وعبد الله بن أبي ربيعة بالهدايا إلى النجاشي ليرد المسلمين، فوقف جعفر أمام النجاشي وبطارقته كالطود الشامخ، وألقى خطبته الدبلوماسية التاريخية: «أيها الملك، كنا قوماً أهل جاهلية، نعبد الأصنام، ونأكل الميتة، ونأتي الفواحش، ونقطع الأرحام، ونسيء الجوار، حتى بعث الله إلينا رسولاً منا، نعرف نسبه وصدقه وأمانته وعفافه، فدعانا إلى الله لنوحده ونعبده...».
ولما سأله النجاشي عما جاء به النبي عن عيسى، قرأ عليه جعفر بصوت خاشع صدر سورة مريم: ﴿كهيعص * ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُ زَكَرِيَّا﴾، فبكى النجاشي حتى اخضلت لحيته وبكت أساقفته، وقال النجاشي: «إن هذا والذي جاء به موسى ليخرج من مشكاة واحدة، انطلقا فلا أسلمهم إليكما أبداً!».

ثانياً: العودة وشوق النبي ﷺ
مكث جعفر بالحبشة يدعو إلى الله حتى هاجر إلى المدينة المنورة سنة 7 هـ، وتزامن قدومه مع فتح خيبر، فلما رآه النبي ﷺ تهلل وجهه نوراً، واعتنقه وقبل ما بين عينيه وقال: «ما أدري بأيهما أنا أفرح: بفتح خيبر أم بقدوم جعفر؟!».
وقال له النبي ﷺ كلمة سجلها التاريخ: «أشبهتَ خَلقي وخُلقي».

ثالثاً: ملحمة مؤتة واستشهاده الخالد
في جمادى الأولى سنة 8 هـ، بعث النبي ﷺ جيش مؤتة إلى مشارف الشام (3 آلاف مقاتل ضد 200 ألف من الروم وحلفائهم)، وجعل القيادة لزيد بن حارثة فإن قُتل فجعفر بن أبي طالب.
فلما استشهد زيد، تناول جعفر الراية بيمينه فقاتل حتى قُطعت يمينه، فأخذ الراية بشماله فقاتل حتى قُطعت شماله، فاحتضن الراية بعضديه إلى صدره وهو ينشد:
يا حبذا الجنةُ واقترابُها ... طيبةً وبارداً شرابُها
والرومُ رومٌ قد دنا عذابُها ... كافرةٌ بعيدةٌ أنسابُها
عليَّ إذ لاقيتُها ضرابُها
وظل قابضاً على الراية حتى استشهد رضي الله عنه ووجدوا في مقدم جسده بضعاً وتسعين ما بين طعنة رمح وضربة سيف دون أن يولي دبره.
ونزل الوحي على النبي ﷺ فأخبر الصحابة باستشهاد القادة وهو يبكي، وقال: «أبدله الله بيديه جناحين يطير بهما مع الملائكة في الجنة حيث شاء!».

ماذا نتعلم من سيرة جعفر الطيار؟
1. قوة الحجة والبلاغة وعرض مبادئ الإسلام بوضوح وعزة أمام الملوك والحكام.
2. الثبات العسكري والفداء التام؛ بذل يديه وروحه لتبقى راية التوحيد مرفوعة.
3. الإحسان إلى الضعفاء والمساكين؛ فكان يعطف عليهم ويطعمهم ويفرح قلوبهم.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب المغازي، باب غزوة مؤتة (حديث 4261)، وباب فضائل جعفر بن أبي طالب (حديث 3709).
• مسند أحمد: مسند بني هاشم، حديث أم سلمة في قصة النجاشي (حديث 1740 وصححه أحمد شاكر).
• سيرة ابن هشام، والبداية والنهاية لابن كثير (أحداث غزوة مؤتة)."""
