      "additionalInfo": "قال عنه النبي ﷺ: «إن العباس عمي وصنو أبي، فمن آذى العباس فقد آذاني».",
      "day": """هو العباس بن عبد المطلب بن هاشم الهاشمي القرشي، كنيته «أبو الفضل»، عم رسول الله ﷺ وأسنّ منه بثلاث سنين، لقبه المسلمون بـ «ساقي الحرمين»؛ لقيامه بسقاية الحجيج وعمارة المسجد الحرام في الجاهلية والإسلام، ولدعاء عمر به في الاستسقاء.

أولاً: حمايته للنبي بمكة وبيعة العقبة
كان العباس رضي الله عنه محباً للنبي ﷺ حريصاً على سلامته، وحضر معه بيعة العقبة الثانية في ظلام الليل بمكة وهو على دين قومه ليوثق للنبي عهده ويطمئن إلى صدق الأنصار، فقال لأهل يثرب: «يا معشر الخزرج، إن محمداً منا حيث قد علمتم، وقد منعناه من قومنا ممن هو على مثل رأينا فيه... فإن كنتم ترون أنكم وافون له بما دعوتموه إليه فأنتم وما تحملتم، وإن كنتم مسلميه بعد الخروج فمن الآن فدعوه!».

ثانياً: إسلامه وجهاده في الفتح وحنين
كان إسلامه قديماً بمكة ويكتم إسلامه لعينه النبي على أخبار قريش، ثم هاجر بأهله علانية قبل فتح مكة بأيام، فالتقى بالنبي بالجحفة وشهد معه فتح مكة.
وفي غزوة حنين، لما باغتت هوازن المسلمين بالسهام وتراجع الجيش، ثبت النبي ﷺ على بغلته البيضاء ينادي «أنا النبي لا كذب، أنا ابن عبد المطلب»، ولم يثبت معه إلا نفر قليل في مقدمتهم العباس آخذاً بلجام بغلة النبي. وكان العباس صيتاً جهوري الصوت، فقال له النبي: «يا عباس، اصرخ: يا أصحاب السمرة! يا أصحاب سورة البقرة!»، فصاح العباس صيحة رجت الوادي: «يا أصحاب السمرة!»، فكر المسلمون كأنهم النحل وعادوا يقاتلون حتى نصرهم الله.

ثالثاً: مكانته النبوية وتوسل عمر بدعائه
كان النبي ﷺ يُجله إجلالاً عظيماً ويقول: «هذا العباس بن عبد المطلب، أجود قريش كفاً وأوصلها رحماً»، وقال: «من آذى العباس فقد آذاني، فإنما عم الرجل صنو أبيه».
وفي خلافة عمر بن الخطاب عام الرمادة حين اشتد القحط، خرج عمر بالمسلمين يستسقون، فأخذ بيد العباس وقال: «اللهم إنا كنا نتوسل إليك بنبينا فتسقينا، وإنا نتوسل إليك بعم نبينا فاسقنا»، ودعا العباس وهو يبكي والدموع تتحدر على لحيته، فما غادروا حتى انهمر المطر وسُقيت الأرض.

رابعاً: وفاته رضي الله عنه
توفي العباس في المدينة المنورة في رجب سنة 32 هـ في خلافة عثمان بن عفان وله من العمر 88 عاماً، وصلى عليه عثمان ودفن بالبقيع بحضور حاشد من الصحابة والمسلمين.

ماذا نتعلم من سيرة العباس بن عبد المطلب؟
1. صلة الرحم وإجلال أعمام النبي ﷺ وآل بيته الأطهار.
2. الثبات والشجاعة في اللحظات الحرجة وقلب مسار المعارك بالنداء الصادق.
3. التواضع وتقديم أهل الصلاح والفضل في الدعاء والاستسقاء لعامة المسلمين.

المصادر والمراجع المعتمدة:
