      "biography": "مصعب بن عمير العبدري القرشي، أبو عبد الله، غرس شجرة الإسلام في يثرب فأسلم على يديه سادة الأنصار، واستشهد بأحد ولم يجدوا له كفناً يكفي جسده.",
