      "day": """هو مصعب بن عمير بن هاشم بن عبد مناف العبدري القرشي، كنيته «أبو عبد الله»، ولُقب بـ «مصعب الخير»، أول سفير في الإسلام وأعظم من دعا إلى الله بالحكمة والموعظة الحسنة.

أولاً: النعيم المكي والتضحية العظمى
كان مصعب فتى مكة المدلل؛ أبهى شبابها جمالاً، وأعطرهم ريحاً، تلبسه أمه خناس بنت مالك أرقى الثياب وتطعمه أطيب الطعام.
فلما بلغه خبر دعوة النبي ﷺ، ذهب إلى دار الأرقم بن أبي الأرقم واستمع إلى آيات القرآن فأنارت بصيرته وأسلم لوقته. ولما علمت أمه حبسته وعذبته وجوّعته ليرتد، فثبت على إيمانه حتى تمكن من الفرار وهاجر إلى الحبشة، تاركاً وراءه كل جاه وزينة ودنيا زائلة في سبيل الله.

ثانياً: أعظم سفير وميلاد مجتمع الأنصار
بعد بيعة العقبة الأولى، اختار النبي ﷺ مصعب بن عمير ليكون سفيره إلى يثرب؛ ليعلم أهلها القرآن ويفقههم في الدين ويعد المدينة لاستقبال الهجرة النبوية.
ودخل مصعب يثرب بالحكمة والرفق، وجاءه سيدا الأوس أسيد بن حضير وسعد بن معاذ شاهرين حِربهما غضباً، فقال لهما مصعب بأدب النبوة وسكينتها: «أوَتجلس فتسمع؟ فإن رضيتَ أمراً قبلتَه، وإن كرهتَه كففنا عنك ما تكره»، فقال أسيد: «أنصفت»، وجلس فقرأ عليه مصعب القرآن، فتهلل وجهه وقال: «ما أحسن هذا الكلام وأجمله! كيف تصنعون إذا أردتم أن تدخلوا في هذا الدين؟»، فأسلم أسيد ثم تبعه سعد بن معاذ، وأسلم بإسلامهما بنو عبد الأشهل جميعاً، فما بقي بيت في المدينة إلا وفيه مسلم، فكان فتح المدينة بالقرآن على يد هذا الفتى القرشي الصادق.

ثالثاً: بطولته واستشهاده في أحد
حمل مصعب راية المهاجرين في بدر الكبرى، ثم حملها يوم أحد. وعندما اضطربت صفوف المسلمين في أحد ثبت مصعب بالراية كالجبل يذود عن النبي ﷺ ليصرف نظر المشركين عنه، فضربه فارس من قريش فقطع يده اليمنى، فأخذ الراية بيده اليسرى وهو يتلو: ﴿وَمَا مُحَمَّدٌ إِلاَّ رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ أَفَإِن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَى أَعْقَابِكُمْ﴾، فقطع يده اليسرى، فضم الراية بعضديه إلى صدره حتى طعنه برمح فخر صريعاً شهيداً رضي الله عنه.
ولما مر النبي ﷺ بجثمانه ورأى ثوبه المرقع بكى بكاءً مراً، وقال: «لقد رأيتك بمكة وما بها أحد أنعم منك ولا أرق ثوباً، وها أنت ذا في نمرة إن غطينا بها رأسك بدت قدماك، وإن غطينا قدميك بدا رأسك!»، فأمر بتغطية رأسه وجعل الإذخر على قدميه، وقرأ: ﴿مِّنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ﴾.

ماذا نتعلم من سيرة مصعب بن عمير؟
1. تقديم العقيدة والآخرة على كل مباهج الدنيا ومغرياتها وشهواتها.
2. أدب الحوار والدعوة إلى الله باللين والإنصاف والإقناع العقلي الهادئ.
3. التضحية العظمى والثبات على المبدأ حتى آخر رمق في الحياة.

المصادر والمراجع المعتمدة:
