أولاً: ملحمة التوحيد في رمضاء مكة
كان بلال عبداً حبشياً لأمية بن خلف الجمحي بمكة، فلما دخل نور الإسلام في قلبه أسلم سراً، فعلم به أمية فأخرجه إلى بطحاء مكة في وقت الظهيرة وقت التهاب الرمال، وألقاه على ظهره وأمر بصخرة عظيمة فأُلقيت على صدره، وقال له: «لا تزال هكذا حتى تموت أو تكفر بمحمد وتعبد اللات والعزى!».
فما زاد بلال وهو يكابد الموت اختناقاً وحراً إلا أن يردد بلسان ملؤه اليقين: «أحدٌ.. أحد! أحدٌ.. أحد!».
ومر به أبو بكر الصديق وهو يعذب، فاشترى بلالاً من أمية وأعتقه لوجه الله، حتى قال عمر بن الخطاب مقولته العادلة: «أبو بكر سيدنا، وأعتق سيدنا!».

ثانياً: مؤذن النبوة وشرف الكعبة
اختاره النبي ﷺ لما شرع الأذان ليكون مؤذنه الخاص لنداوة صوته وحسن أدائه؛ فقال لعبد الله بن زيد بعد رؤيا الأذان: «قم مع بلال فألقِ عليه ما رأيت فليؤذن به، فإنه أندى صوتاً منك».
وظل بلال يصدح بالأذان في حضر النبي وسفره ومغازيه، حتى كان يوم فتح مكة الأعظم؛ فأمره النبي ﷺ أن يرتقي ظهر الكعبة المشرفة فوق أصنام الجاهلية المحطمة، فصدح بأذان التوحيد أمام آلاف المشركين في مشهد خلدته ذاكرة التاريخ.

ثالثاً: مكانته في الجنة وثباته بعد النبي
ثبت في الصحيحين أن رسول الله ﷺ قال لبلال بعد صلاة الفجر: «يا بلال، حدثني بأرجى عمل عملته في الإسلام، فإني سمعت دفّ نعليك بين يديّ في الجنة!»، فقال بلال: «ما عملتُ عملاً أرجى عندي من أني لم أتطهر طهوراً في ساعة من ليل أو نهار إلا صليتُ بذلك الطهور ما كُتب لي أن أصلي».
ولما توفي النبي ﷺ، لم يستطع بلال أن يؤذن بالمدينة؛ فكان إذا وصل إلى قوله «أشهد أن محمداً رسول الله» غلبته العبرة وخنقته الدموع، فاستأذن أبا بكر في الخروج مجاهداً ومرابطاً في أرض الشام.

رابعاً: وفاته رضي الله عنه
عاش في الشام مرابطاً حتى حضرته الوفاة بدمشق سنة 20 هـ، وكانت زوجته تقول بجواره: «واحزناه!»، فكان يرفع الغطاء عن وجهه وهو يبتسم ويقول: «بل واطرباه! غداً نلقى الأحبة.. محمداً وصحبه!».

ماذا نتعلم من سيرة بلال بن رباح؟
1. عظمة التوحيد واليقين؛ الإيمان إذا خالطت بشاشته القلوب هانت دونه كل تضحيات الدنيا.
2. أن معيار التفاضل في الإسلام هو التقوى والعمل الصالح لا النسب ولا اللون.
3. المداومة على ركعتي سنة الوضوء والحرص على الطهارة الدائمة.

