      "day": """هو سلمان الفارسي، كنيته «أبو عبد الله»، لُقب بـ «سلمان الخير» و«الباحث عن الحقيقة»، الصحابي الجليل الذي قطع آلاف الأميال بحثاً عن الدين الحق، وسابق الفرس إلى الإسلام.

أولاً: رحلة البحث الشاقة عن النور
نشأ سلمان في قرية «جي» بأصبهان في بلاد فارس، وكان أبوه دهقان القرية يعبد النار، فحبسه أبوه في البيت لفرط محبته له. لكن سلمان رأى بطلان المجوسية، ففر وتبع النصارى، وتنقل بين رهبان الشام، ثم الموصل، ثم نصيبين، ثم عمورية باحثاً عن التوحيد الخالص.
وعندما احتضر راهب عمورية قال له: «يا بني، ما أعلم أحداً على مثل ما كنا عليه، ولكن قد أظلك زمان نبي يُبعث بدين إبراهيم، يخرج بأرض العرب، يهاجر إلى أرض بين حرتين بينهما نخل، وله علامات لا تخفى: يأكل الهدية، ولا يأكل الصدقة، وبين كتفيه خاتم النبوة».
فخرج سلمان مع قافلة من كلب، فغدروا به وباعوه عبداً ليهودي، حتى نقله مشترٍ آخر إلى يثرب، فلما رآها سلمان عرف نخلها وحرتها فاستيقن أنها دار هجرة النبي الموعود.

ثانياً: التحقق من النبوة والحرية
عندما قدم النبي ﷺ قباء، ذهب سلمان ومعه تمر وقال: «هذه صدقة»، فأمر النبي أصحابه فأكلوا ولم يأكل هو، فقال سلمان في نفسه: «هذه واحدة».
ثم أتاه بالمدينة ومعه تمر وقال: «هذه هدية أهديها لك»، فأكل النبي منها وأمر أصحابه فأكلوا، فقال سلمان: «هذه ثنتان».
ثم تبع النبي ﷺ في جنازة بالبقيع، فتفطن النبي ﷺ لما يريد فألقى رداءه عن ظهره، فنظر سلمان فرأى خاتم النبوة بين كتفيه كبيضة الحمامة يتلألأ نوراً، فانكب عليه يقبله ويبكي، وأسلم لله رب العالمين.
وأعانه النبي والصحابة على مكاتبة سيده اليهودي؛ فغرس له النبي ثلاثمائة نخلة بيده الشريفة ووزن له أوقية ذهب حتى تحرر سلمان وصار حراً.

ثالثاً: عبقرية الخندق ومكانته الرفيعة
في شوال سنة 5 هـ، لما تجمعت أحزاب الشرك (عشرة آلاف مقاتل) لاستئصال المسلمين في المدينة، جمع النبي أصحابه للشورى، فتقدم سلمان بفكرة عسكرية لم تعهدها العرب وقال: «يا رسول الله، إنا كنا بأرض فارس إذا حُوصرنا خندقنا حولنا»، فاستحسن النبي فكرته وأمر بحفر الخندق شمال المدينة، وكان سبباً حاسماً في صد الأحزاب ونجاة المسلمين.
وتنافس المهاجرون والأنصار كل يريد نسبة سلمان إليه؛ فقال المهاجرون: «سلمان منا»، وقال الأنصار: «سلمان منا»، وتذكر كتب السيرة والتاريخ أن النبي ﷺ قال إكراماً له: «سلمان منا أهل البيت» في عبارة اشتهرت تاريخياً بفضل هذا الصحابي الجليل.

رابعاً: زهده وعمله اليدوي ووفاته
تولى إمارة المدائن في خلافة عمر وعثمان، وكان راتبه خمسة آلاف درهم يتصدق بها كلها، ويأكل من كسب يده بخوص النخل يبيع الزنبيل بدرهمين فيتصدق بدرهم ويقتات بدرهم، وكان يفترش الأرض ويلبس عباءة صوف خشنة إذا رآه الناس ظنوه خادماً.
توفي رضي الله عنه في المدائن سنة 36 هـ وقد جاوز مائة عام، وترك للأمة مثلاً خالداً في التجرد لله وطلب الحق.

ماذا نتعلم من سيرة سلمان الفارسي؟
1. السعي الدؤوب والجهاد المضني للبحث عن الحق والاستعداد للتضحية بالمال والحرية في سبيله.
2. الانفتاح على الحكمة والتجارب النافعة؛ «الحكمة ضالة المؤمن أنى وجدها فهو أحق بها».
3. الزهد في المناصب والاعتماد على الكسب الحلال من عمل اليد.

