      "day": """هو جُندب بن جنادة الغفاري، كنيته «أبو ذر»، من كبار السابقين إلى الإسلام؛ كان رابع أو خامس رجل دخل في هذا الدين، ومضرب المثل في الزهد وصدق اللهجة.

أولاً: نبذة وإسلامه وجهره بالدعوة بمكة
كان أبو ذر رضي الله عنه يتأله في جاهليته وينبذ عبادة الأوثان، فلما بلغه مبعث النبي ﷺ قدم مكة سراً حتى لقي النبي وسمع كلامه فأسلم من فوره.
فقال له النبي ﷺ: «يا أبا ذر، اكتم هذا الأمر وارجع إلى قومك»، لكن حمية الإيمان والصدع بالحق غلبت عليه، فقال: «والذي نفسي بيده، لا أكتمها حتى أصرخ بها بين أظهرهم!». فمضى إلى المسجد الحرام ونادى بأعلى صوته بين قريش: «أشهد أن لا إله إلا الله، وأشهد أن محمداً عبده ورسوله!»، فوثب عليه المشركون فضربوه ضرباً مبرحاً حتى كادوا يقتلونه، فأنقذه العباس بن عبد المطلب محذراً قريشاً من قطع غفار لطريق قوافلهم إلى الشام. ثم عاد وفعلها في اليوم التالي فضربوه مجدداً، فضرب مثلاً في الجرأة والشجاعة الإيمانية.

ثانياً: دعوته لقومه وثباته
رجع إلى قبيلته غفار يدعوهم إلى الإسلام، فأسلم نصف القبيلة على يديه، فلما قدم النبي ﷺ المدينة المنورة جاءه أبو ذر ومعه قبيلته غفار وأسلمت معهم أسلم، فدعا النبي ﷺ بدعوته الشهيرة: «غفار غفر الله لها، وأسلم سالمها الله».
وفي غزوة تبوك، أبطأ بعير أبي ذر فعجز عن اللحاق بالجيش، فنزل أبو ذر وحمل متاعه على ظهره ومشى على قدميه وحيداً في هجير الصحراء القاتل، فلما تراءى للنبي شخص قادم من بعيد قال: «كن أبا ذر!»، فلما عرفوه قال النبي ﷺ كلمته النبوية الصادقة: «رحم الله أبا ذر؛ يمشي وحده، ويموت وحده، ويُبعث وحده!».

ثالثاً: صدق اللهجة وزهده التام
شهد له رسول الله ﷺ بأعظم وسام صدق في التاريخ؛ فقال ﷺ: «ما أظلت الخضراء ولا أقلت الغبراء من ذي لهجة أصدق من أبي ذر، من سره أن ينظر إلى تواضع عيسى بن مريم فلينظر إلى أبي ذر».
وكان شديد الزهد، لا يقتني ديناراً ولا درهماً، ويأخذ بظاهر نصوص تحريم كنز الذهب والفضة والإنفاق الفوري في سبيل الله، وكان يرى أن المسلم لا يدخر إلا قوت يومه.

رابعاً: وفاته وحيداً بالربذة
في خلافة عثمان بن عفان رضي الله عنه، اعتزل أبو ذر الناس وسكن منطقة «الربذة» في الصحراء، ولما حضرته الوفاة سنة 32 هـ بكت زوجته لعدم وجود ثوب يكفنه ولا من يغسله، فقال لها: «أبشري، فإني سمعت رسول الله ﷺ يقول: ليموتن رجل منكم بفلاة من الأرض يشهده عصابة من المؤمنين، وما بقي من أولئك النفر أحد إلا ومات في قرية وجماعة، وأنا الذي أموت بفلاة».
فبينما هم كذلك، إذا بقافلة مقبلة من العراق فيها الصحابي الجليل عبد الله بن مسعود وجماعة من المؤمنين، فنزلوا مسرعين وغسلوه وكفنه ابن مسعود في ثوب له وبكى على قبره رضي الله عنه محققاً نبوءة النبي ﷺ.

ماذا نتعلم من سيرة أبي ذر الغفاري؟
1. الصدق المطلق والجرأة في إعلان الحق دون مواربة أو نفاق.
