      "day": """هو عمار بن ياسر بن عامر العنسي المذحجي، كنيته «أبو اليقظان»، وأمه سمية بنت خياط أول شهيدة في الإسلام، وأبوه ياسر أول شهيد في الإسلام؛ أسرة آل ياسر الطاهرة التي نزلت فيها بشارات النبوة الخالدة.

أولاً: عذاب بطحاء مكة وبشارة الجنة
أسلم عمار قديماً بمكة في دار الأرقم، فكان من أوائل سبعة أظهروا الإسلام.
أذاقه مشركو قريش ألوان العذاب؛ فكانوا يخرجونه مع أبيه وأمه إلى رمضاء مكة الملتهبة ويسومونهم سوء العذاب، وكان رسول الله ﷺ يمر بهم وهم يتلوون من الألم فلا يملك لهم إلا التثبيت بالبشارة الربانية العظمى: «صبراً آل ياسر، فإن موعدكم الجنة!».
واستشهدت أمه سمية بطعنة أبي جهل الغادرة، واستشهد أبوه ياسر تحت العذاب، وظل عمار يعذب بالنار حتى قال كلمة مفرجة مكرهاً، فجاء يبكي إلى النبي ﷺ يقول: «يا رسول الله، ما تُرِكتُ حتى نلتُ منك وذكرتُ آلهتهم بخير!»، فقال له النبي بحنان النبوة: «كيف تجد قلبك؟»، قال: «مطمئناً بالإيمان»، فقال ﷺ: «فإن عادوا فعُد»، وأنزل الله قرآناً يُتلى إلى يوم الدين تبرئة لعمار: ﴿مَن كَفَرَ بِاللَّهِ مِن بَعْدِ إِيمَانِهِ إِلاَّ مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالإِيمَانِ﴾.

ثانياً: بناء أول مسجد ومناقبه العظيمة
هاجر عمار إلى المدينة المنورة، وشارك في بناء مسجد قباء؛ فكان يحمل في البناء لبنتين لبنتين بينما الناس يحملون لبنة لبنة، فرآه النبي ﷺ فنفض التراب عن رأسه وقال برحمة: «ويح عمار، يدعوهم إلى الجنة ويدعونه إلى النار!».
وكان النبي ﷺ يحبه ويثني على إيمانه الصافي فقال: «مُلئ عمار إيماناً إلى مُشاشه» (أي حتى عروقه وعظامه)، وقال ﷺ: «عمار جُلدة ما بين عيني وأنفي»، وقال: «إذا اختلف الناس فابن سمية مع الحق ومع الكتاب».

ثالثاً: جهاده وبطولته واستشهاده بصفين
شهد عمار بدراً وأحداً والمشاهد كلها، وفي حروب الردة باليمامة وثب على صخرة وقد قُطعت أذنه تتدلى وهو يصيح بالمسلمين: «يا معشر المسلمين، أمن الجنة تفرون؟! أنا عمار بن ياسر، هلموا إليّ!»، فكان صوته دافعاً للنصر.
وعاش حتى جاوز التسعين من عمره مجاهداً مع علي بن أبي طالب، وفي معركة صفين سنة 37 هـ، تقدم عمار يقاتل وهو ينشد: «اليوم نلقى الأحبة.. محمداً وحزبه»، فضربه رجلان فقتلاه وهو ابن 93 سنة، فاستحضر الصحابة حديث رسول الله ﷺ المشهور في صحيح البخاري: «ويح عمار، تقتله الفئة الباغية»، فكان مقتله علامة فارقة بيّنت الحق لأهل ذلك الزمان.

ماذا نتعلم من سيرة عمار بن ياسر؟
1. عظمة الصبر والاحتساب عند التعذيب والابتلاء في سبيل العقيدة.
2. رحمة الشريعة الإسلامية ورعايتها لأحكام الإكراه وطمأنينة القلب بالإيمان.
3. الثبات على الحق والجهاد لنصرته حتى أرذل العمر دون كلل أو تراجع.

