      "day": """هو معاذ بن جبل بن عمرو بن أوس الأنصاري الخزرجي، كنيته «أبو عبد الرحمن»، من كبار فقهاء الصحابة وقرائهم، شهد له النبي ﷺ بأنه أعلم الأمة بالأحكام.

أولاً: إسلامه ونشأته العلمية
أسلم معاذ وهو فتى غض في الثامنة عشرة من عمره في بيعة العقبة الثانية، وكان شاباً وضيء الوجه، كحيل العينين، براق الثنايا.
ولازم رسول الله ﷺ ملازمة تامة فحفظ القرآن كله في حياة النبي، وعكف على فهم معاني الآيات وأسرار الأحكام حتى فاق أقرانه؛ وقال النبي ﷺ فيه: «أعلم أمتي بالحلال والحرام معاذ بن جبل، وأقرؤهم لكتاب الله أبيّ بن كعب».
وثبت في سنن أبي داود بسند صحيح أن النبي ﷺ أخذ بيده يوماً وقال له بمحبة غامرة: «يا معاذ، والله إني لأحبك! والله إني لأحبك! أوصيك يا معاذ: لا تدعنّ في دبر كل صلاة أن تقول: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك».

ثانياً: سفارته وقضاؤه في اليمن
بعد فتح مكة وغزوة تبوك، اختاره النبي ﷺ ليكون قاضياً ومعلماً وأميراً على أهل اليمن ليفقههم في دينهم ويجمع زكواتهم؛ وسأله النبي قبل انطلاقه: «بم تقضي يا معاذ؟»، قال: «بكتاب الله»، قال: «فإن لم تجد؟»، قال: «بسنة رسول الله»، قال: «فإن لم تجد؟»، قال: «أجتهد رأيي ولا آلو»، فضرب النبي ﷺ على صدره وقال: «الحمد لله الذي وفّق رسولَ رسولِ الله لما يرضي رسولَ الله!».
ومشى النبي ﷺ يودعه ومعاذ راكب، وقال له مودعاً: «يا معاذ، إنك عسى ألا تلقاني بعد عامي هذا، ولعلك أن تمر بمسجدي هذا وقبري»، فبكى معاذ جشعاً لفراق النبي ﷺ.

ثالثاً: مكانته في الآخرة ووفاته في طاعون عمواس
شهد له النبي ﷺ بمقام رفيع بين العلماء يوم القيامة فقال: «يأتي معاذ بن جبل يوم القيامة يقدُم العلماء برتوة» (أي برمية حجر أو خطوة شرف).
وفي خلافة عمر، خرج معاذ إلى الشام يعلم الناس القرآن ويفقههم، ولما استشهد أبو عبيدة في طاعون عمواس سنة 18 هـ تولى معاذ إمرة الجيش، فما لبث أن أُصيب بالطاعون في راحته، فكان يقلبها ويقبلها ويقول: «اللهم اجعلها بركة، ما أحب أن لي بها شيئاً من الدنيا!»، وفاضت روحه وهو ابن نحو ثلاث وثلاثين سنة في الأردن.

