      "day": """هو حذيفة بن حُسيل (الملقب باليمان) العبسي، كنيته «أبو عبد الله»، حليف الأنصار بالمدينة، صاحب سر رسول الله ﷺ في المنافقين وأبصر الصحابة بأبواب الفتن.

أولاً: نبذة وموقفه المؤثر يوم أحد
أسلم حذيفة مع أبيه اليمان، وقَدِما المدينة فشهد حذيفة المشاهد كلها.
وفي غزوة أحد، وقعت مأساة مؤلمة؛ إذ دخل أبوه اليمان في غمار المعركة وهو شيخ كبير، فالتبس أمره على المسلمين وظنوه من المشركين فباشروه بالسيوف، وجعل حذيفة يصرخ بأعلى صوته: «أي عباد الله، أبي! أبي!»، فلم يفهموا لشدة القتال حتى قتلوه خطأً، فقال حذيفة بقلب مؤمن بارّ ممتلئ رحمة وعفواً: «يغفر الله لكم، وهو أرحم الراحمين!»، وتصدق بديته على فقراء المسلمين، فازداد النبي ﷺ له حباً وإجلالاً.

ثانياً: مهمة ليلة الأحزاب الاستخباراتية الأسطورية
في غزوة الخندق في ليلة شاتية مظلمة شديدة البرد والريح، دعا النبي ﷺ وقال: «من رجل يقوم فينظر ما فعل القوم ثم يرجع وله الجنة؟»، فما قام أحد من شدة الجوع والبرد والخوف، فسمى النبي ﷺ حذيفة بالاسم: «قم يا حذيفة فائتني بخبر القوم، ولا تذعرهم عليّ».
فمضى حذيفة في الظلام الحالك وتسلل إلى معسكر الأحزاب والريح تقتلع خيامهم وتكفأ قدورهم، وجلس بين رجال قريش حتى رأى أبا سفيان يصطلي بالنار، قال حذيفة: «فوضعتُ السهم في كبد القوس وأردتُ قتله، فذكرتُ وصية رسول الله: ولا تذعرهم عليّ، فرددتُ سهمي»، وعاد إلى النبي ﷺ بأخبار ارتحال المشركين واندحارهم.

ثالثاً: صاحب السر النبوي في المنافقين
ائتمنه رسول الله ﷺ على أسماء المنافقين بالمدينة ومؤامراتهم واحداً واحداً، ولم يخبر بها سواه حتى أبي بكر وعمر.
وكان عمر بن الخطاب في خلافته إذا مات رجل يسأل: «هل حضر حذيفة الصلاة عليه؟»، فإن حضر صلى عليه عمر وإلا لم يُصلِّ عليه. وجاء عمر يوماً لحذيفة يناشده بدموع خاشعة: «يا حذيفة، أنشدك بالله، أسماني لك رسول الله ﷺ في المنافقين؟!»، فقال حذيفة: «لا يا أمير المؤمنين، ولا أزكي بعدك أحداً».

رابعاً: فتوحاته ووفاته
ولاه عمر المدائن، وقاد معركة نهاوند («فتح الفتوح») بعد استشهاد النعمان بن مقرن حتى فتح الله على المسلمين.
وكان يقول: «كان الناس يسألون رسول الله ﷺ عن الخير، وكنت أسأله عن الشر مخافة أن يدركني».
توفي رضي الله عنه بالمدائن سنة 36 هـ بعد مقتل عثمان بأربعين يوماً، تاركاً للأمة مدرسة في حفظ الأمانة والفطنة والبصيرة.

ماذا نتعلم من سيرة حذيفة بن اليمان؟
1. العفو والصفح الجميل واحتساب المصائب العائلية لله تعالى.
2. الانضباط العسكري الدقيق وطاعة أوامر القيادة حتى مع توافر الفرص المغرية للمخالفة.
3. حفظ الأسرار والأمانات وعدم إفشائها لأقرب الناس مهما بلغت الضغوط.

المصادر والمراجع المعتمدة:
