      "day": """هو خالد بن الوليد بن المغيرة المخزومي القرشي، كنيته «أبو سليمان»، لقبه رسول الله ﷺ بـ «سيف الله المسلول»، أحد أعظم القادة العسكريين في التاريخ البشري، لم يخسر معركة قط في الجاهلية ولا في الإسلام.

أولاً: إسلامه وانقلاب الموازين
كان خالد فارساً مقداماً في الجاهلية وقائداً لفرسان قريش. وفي صفر سنة 8 هـ، شرح الله صدره للإسلام فخرج من مكة ومعه عمرو بن العاص وعثمان بن طلحة قاصدين المدينة، فلما رآهم النبي ﷺ استبشر وقال: «رمتكم مكة بأفلاذ كبدها!».
وجاء خالد فأسلم وبايع النبي ﷺ، فقال: «يا رسول الله، استغفر لي كل ما سلف مني من عداوة لك»، فقال ﷺ: «الإسلام يجبّ ما قبله»، ودعا له النبي بالخير والتثبيت.

ثانياً: معجزة مؤتة ولقب سيف الله
كان اختباره العسكري الأول في الإسلام في غزوة مؤتة سنة 8 هـ؛ حيث واجه ثلاثة آلاف مسلم مائتي ألف مقاتل من الروم وحلفائهم، واستشهد القادة الثلاثة الذين عينهم النبي (زيد وجعفر وابن رواحة).
فأجمع المسلمون على تسليم الراية لخالد بن الوليد وهو جندي بلا رتبة، فأدار المعركة بعبقرية مذهلة؛ كسر يومها تسعة أسياف في يده ولم يثبت إلا صفيحة يمانية، ثم غير ترتيب الجيش في الليل (جعل الميمنة ميسرة والميسرة ميمنة والساقة في المقدمة وأثار الغبار بالخيل)، فأوهم الروم بقدوم إمدادات ضخمة، وانسحب بالجيش كاملاً دون أن يجرؤ الروم على مطاردته.
وفي المدينة، كان النبي ﷺ ينقل لأصحابه أحداث المعركة بالوحي وهو يبكي حتى قال: «حتى أخذ الراية سيفٌ من سيوف الله، حتى فتح الله عليهم»، ومن يومها سُمي «سيف الله المسلول».

ثالثاً: حروب الردة وفتوحات العراق والشام
بعد وفاة النبي ﷺ، قاد خالد جيوش الردة في خلافة أبي بكر، وحسم معركة اليمامة ضد مسيلمة الكذاب ببسالة خارقة.
ثم أمره الصديق بالتوجه إلى العراق، ففتح الحيرة ودك حصون الفرس في معارك متتالية، ثم أمره بالنجدة السريعة لجيوش الشام، فقام بأعظم مناورة عسكرية بقطع صحراء السماوة القاحلة في خمسة أيام وخرج وراء خطوط الروم.
وقاد معركة اليرموك الخالدة سنة 15 هـ بحنكة تكتيكية فريدة أسقطت إمبراطورية الروم في بلاد الشام، وعندما جاءه أمر أمير المؤمنين عمر بن الخطاب بعزله وتولية أبي عبيدة وهو في قلب المعركة، نزل عن القيادة بكل تجرد وقال: «إني لا أقاتل لعمر، إنما أقاتل لرب عمر!».

رابعاً: كلماته الأخيرة ورحيله الحزين
عاش زاهداً لا يبتغي إلا الشهادة في سبيل الله، وتوفي على فراشه في حمص سنة 21 هـ، وبكى عند وفاته قائلاً كلمته الخالدة التي خفقت بها رايات المجد: «لقد شهدتُ مائة زحف أو زهاءها، وما في جسدي موضع شبر إلا وفيه ضربة بسيف أو طعنة برمح أو رمية بسهم، وها أنا ذا أموت على فراشي كما يموت البعير! فلا نامت أعين الجبناء! ما كان لي من عمل أرجى بعد لا إله إلا الله من ليلة بتّها في سبيل الله وأنا متترس والسماء تسكب مطراً أنتظر الصبح لأغير على الكفار!».

ماذا نتعلم من سيرة سيف الله المسلول؟
1. توظيف الموهبة والعبقرية القيادية والعسكرية في نصرة الدين وإعلاء كلمة الله.
2. التجرد المطلق ونكران الذات؛ قاتل جندياً مخلصاً بنفس الحماس والبطولة التي قاتل بها قائداً عاماً.
3. الصدق في طلب الشهادة؛ مات على فراشه وكتب الله له أجر الشهداء بصدق نيته.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب المغازي، باب غزوة مؤتة (حديث 4261، 4262).
• صحيح مسلم: كتاب الفضائل (حديث 2498).
• تاريخ دمشق لابن عساكر، والبداية والنهاية لابن كثير (أحداث فتوح الشام وسيرة خالد)."""
