      "battles": ["سرية ذات السلاسل","فتح مكة","غزوة حنين","غزوة الطائف","غزوة تبوك"],
      "attributes": ["داهية العرب","فاتح مصر","أمير ذات السلاسل","مؤمن بأمر النبوة"],
