      "day": """هو عمرو بن العاص بن وائل السهمي القرشي، كنيته «أبو عبد الله»، لُقب بـ «داهية العرب» لرجاحة عقله وشدة دهائه وحنكته السياسية والعسكرية، وفاتح أرض الكنانة مصر.

أولاً: إسلامه وشهادة النبي له بالإيمان
كان عمرو في الجاهلية أحد فرسان قريش وسفرائها، ومضى إلى النجاشي ليرد مهاجري الحبشة. لكن نور الحق استقر في قلبه، فخرج في صفر سنة 8 هـ مسافراً إلى المدينة ليعلن إسلامه، والتقى بخالد بن الوليد في الطريق فدخلا معاً.
ولما بسط يده ليبايع النبي ﷺ قبض يده، فقال النبي: «ما لك يا عمرو؟»، قال: «أردت أن أشترط»، قال: «تشترط ماذا؟»، قال: «أن يُغفر لي»، فقال النبي كلمته المطمئنة: «أما علمتَ يا عمرو أن الإسلام يهدم ما كان قبله، وأن الهجرة تهدم ما كان قبلها، وأن الحج يهدم ما كان قبله؟!».
وثبت في سنن الترمذي بسند صحيح أن النبي ﷺ قال: «أسلم الناس، وآمن عمرو بن العاص».

ثانياً: قيادة سرية ذات السلاسل
بعد إسلامه بأشهر يسيرة، عقد له النبي ﷺ لواء غزوة «ذات السلاسل» في جمادى الآخرة سنة 8 هـ لقتال قضاعة شمال شبه الجزيرة، وأمّره على جيش فيه كبار المهاجرين كأبي بكر وعمر بن الخطاب لفرط دهائه ومعرفته بمسالك العرب.
وأظهر فيها حكمة عسكرية بارعة؛ فأمرهم ألا يوقدوا ناراً في الليل لئلا يراهم العدو، وتيمم بالتراب وصلى بهم وهو جنب لشدة البرد القارس، فلما عادوا واشتكوه للنبي ﷺ تبسم النبي وقال لعمرو لما شرح له خوفه من البرد مستدلاً بقوله تعالى: ﴿وَلاَ تَقْتُلُواْ أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيماً﴾، فأقرّه النبي ﷺ على اجتهاده وفقهه.

ثالثاً: فتح مصر وبناء حاضرة الفسطاط
في خلافة عمر بن الخطاب، عرض عمرو خطة استراتيجية لفتح مصر لحماية الشام؛ فسار بجيشه سنة 19 هـ وفتح العريش والفرما وبلبيس وحصن بابليون بعد حصار طويل، ثم سار إلى الإسكندرية ففتحها وأمّن أقباط مصر وكنائسهم وأعاد البطريرك بنيامين إلى كرسيه بعد اضطهاد الروم له.
وأسس مدينة «الفسطاط» وبنى فيها أول مسجد في إفريقيا (جامع عمرو بن العاص)، فصارت مصر حاضرة الإسلام الكبرى وسند جيوش المسلمين.

رابعاً: توبته وبكاؤه عند الوفاة
مرض مرض الموت بمصر سنة 43 هـ، فبكى طويلاً وحوّل وجهه إلى الجدار، فقال له ابنه عبد الله بن عمرو: «يا أبت، أما بشرك رسول الله بكذا؟»، فأقبل بوجهه وقال: «إن أفضل ما نعد شهادة أن لا إله إلا الله وأن محمداً رسول الله، إني كنت على أطباق ثلاث: لقد رأيتني وما أحد أشد بغضاً لرسول الله مني، فلو مت على تلك الحال لكنت من أهل النار. ثم جعل الله الإسلام في قلبي فبايعت النبي وكان أحب الناس إلي، فلو مت على تلك الحال لرجوت أن أكون من أهل الجنة. ثم ولينا أموراً لا أدري ما حالي فيها.. فإذا أنا مت فلا تصحبني نائحة ولا نار، فإذا دفنتموني فسنوا عليّ التراب سناً، ثم أقيموا حول قبري قدر ما تُنحر جزور ويُقسم لحمها حتى أستأنس بكم وأنظر ماذا أراجع به رسل ربي!».

ماذا نتعلم من سيرة عمرو بن العاص؟
1. توظيف الدهاء والفطنة والذكاء العقلي لخدمة مصالح الإسلام ونشر رسالته.
2. مرونة الفقه وسعة الشريعة في الأخذ بالرخص وحفظ النفس عند المشقة.
3. الخوف من الله واستشعار المحاسبة الذاتية عند دنو الأجل ولقاء الله.

المصادر والمراجع المعتمدة:
• صحيح مسلم: كتاب الإيمان، باب كون الإسلام يهدم ما قبله (حديث 121)، وحديث وفاته.
• سنن الترمذي: كتاب المناقب، باب مناقب عمرو بن العاص (حديث 3844 وصححه الألباني).
• فتوح مصر والمغرب لابن عبد الحكم، وتاريخ الطبري (أحداث فتح مصر)."""
