      "day": """هو عبد الرحمن بن صخر الدوسي، كنيته «أبو هريرة»، كنّاه بها رسول الله ﷺ حين رآه يحمل هرة صغيرة في كمه يعطف عليها ويسقيها، الصحابي الجليل وأكثر الصحابة رواية وحفظاً لحديث رسول الله ﷺ، حيث حفظ للأمة آلاف الأحاديث النبوية المطهرة.

أولاً: إسلامه وملازمة أهل الصفة
قدم أبو هريرة من بلاد دوس في اليمن سنة 7 هـ معلناً إسلامه تزامناً مع فتح خيبر، وكان فقيراً لا دار له ولا مال، فاستوطن «صفة المسجد النبوي» في المدينة وكان عريف أهل الصفة.
فرغ نفسه تماماً لملازمة رسول الله ﷺ؛ فبينما كان المهاجرون يشغلهم الصفق في الأسواق والأنصار تشغلهم أموالهم وحوائطهم وزروعهم، كان أبو هريرة يتبع النبي ﷺ على ملء بطنه أينما حل وارتحل، يشهد إذا غابوا، ويحفظ إذا نسوا.

ثانياً: معجزة الحفظ ودعاء النبي له
شكا أبو هريرة للنبي ﷺ أنه يسمع منه الأحاديث الكثيرة فينساها، فقال له النبي ﷺ: «ابسط رداءك!»، فبسط كساءه، فغرف النبي ﷺ بيديه الشريفتين في الهواء ثلاثاً وأفرغها في كساء أبي هريرة، ثم قال: «ضمّه إلى صدرك!»، فضمّه، قال أبو هريرة: «فوالذي بعثه بالحق، ما نسيتُ حديثاً سمعتُه منه بعد ذلك اليوم أبداً!».
ودعا النبي ﷺ له ولأمه بدعوة استجيبت من فورها؛ إذ كانت أمه مشركة تؤذيه في النبي، فدعا لها النبي بالهداية فرجع أبو هريرة فوجدها تغتسل وأعلنت إسلامها، ودعا لهما النبي فقال: «اللهم حبب عُبيدك هذا وأمه إلى عبادك المؤمنين، وحبب إليهم المؤمنين».

ثالثاً: عبادته وتقسيم الليل
كان رضي الله عنه مع سعة علمه وروايته عابداً قانتاً؛ يقسم الليل أثلاثاً: ثلثاً ينام، وثلثاً يقوم يصلي، وثلثاً يراجع أحاديث رسول الله ﷺ.
وكان يقسم قيام الليل بينه وبين زوجته وخادمه؛ فإذا صلى هذا أيقظ هذا، فلا يمر جزء من الليل في بيته إلا وفيه قائم يتلو كتاب الله ويذكره.

رابعاً: وفاته ودفاع العلماء عن أمانته
روى عن النبي ﷺ أكثر من خمسة آلاف حديث، وكان أئمة الصحابة كعائشة وابن عمر والتابعين يرجعون إليه في ضبط الروايات.
توفي رضي الله عنه في المدينة المنورة سنة 59 هـ وهو ابن ثمان وسبعين سنة، ودُفن بالبقيع بعد أن أدى أمانة البلاغ وحفظ دين الأمة إلى يوم القيامة.

ماذا نتعلم من سيرة أبي هريرة؟
1. التفرغ لطلب العلم الشرعي وبذل الجهد والصبر على الفقر والجوع في سبيله.
2. بر الوالدين والحرص الشديد على هدايتهما والدعاء لهما بالخير.
3. التوازن البديع بين العلم الشرعي والعبادة العملية وقيام الليل.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب العلم، باب حفظ العلم (حديث 118، 119)، وكتاب فضائل الصحابة (حديث 3768).
• صحيح مسلم: كتاب الفضائل، باب من فضائل أبي هريرة الدوسي (حديث 2492، 2493).
• سير أعلام النبلاء للذهبي (ترجمة أبي هريرة الحافظ)."""
