      "attributes": ["خادم الرسول","مستجاب الدعوة","صاحب بستان الفاكهة","راوية الحديث"],
      "additionalInfo": "قال: خدمت رسول الله ﷺ عشر سنين، فما قال لي أف قط، ولا قال لشيء فعلته لم فعلته، ولا لشيء تركته لم تركته.",
      "day": """هو أنس بن مالك بن النضر الأنصاري الخزرجي، كنيته «أبو حمزة»، لقبه النبي ﷺ بـ «خادمي» و«ابني»، خادم رسول الله ﷺ الأمين، وأحد المكثرين لرواية الحديث النبوي.

أولاً: أمه العظيمة والالتحاق بخدمة النبوة
لما قدم النبي ﷺ المدينة مهاجراً، أقبلت أمه الصحابية الجليلة أم سليم بنت ملحان تقود أنساً وهو غلام صغير ابن عشر سنين، فقالت: «يا رسول الله، هذا أُنيس ابني غلامٌ لبيب كاتب، أهديته إليك ليخدمك، فادعُ الله له!».
فقبل النبي ﷺ الهدية ومسح على رأس أنس ودعا له بدعوة مباركة: «اللهم أكثر ماله وولده، وأطل عمره، واغفر ذنبه، وأدخله الجنة!».

ثانياً: عشر سنين في مدرسة الرحمة النبوية
لازم أنس رسول الله ﷺ ليلاً ونهاراً وسفراً وحضراً عشر سنوات كاملة حتى قبض الله نبيه؛ ونقل للأمة أرق تفاصيل أخلاقه ومعاملته فقال: «خدمتُ رسول الله ﷺ عشر سنين، فواللهِ ما قال لي قط: أُفٍّ، ولا قال لشيء فعلتُه: لِمَ فعلتَه؟ ولا لشيء لم أفعلْه: ألا فعلتَه؟ وكان رسول الله ﷺ من أحسن الناس خُلقاً».
وكان النبي ﷺ يلاطفه ويناديه: «يا بنيّ»، ويدخل بيت أمه أم سليم فيقيل عندهم ويبارك في طعامهم.

ثالثاً: تحقق الدعوة النبوية بالبركة والولد
تحققت دعوة النبي ﷺ لأنس بن مالك بحذافيرها؛ فطال عمره حتى جاوز مائة عام، وكان أكثر الأنصار مالاً، وكان له بستان يحمل الفاكهة في السنة مرتين، وكان فيه ريحان يشم منه ريح المسك.
ورزقه الله من صلبه أكثر من مائة ولد وحفيد رآهم في حياته، وكان يقول: «والله إني لأرى اثنتين من دعوة النبي: كثرة مالي وولدي، وإني لأرجو الثالثة: الجنة!».
وكان مستجاب الدعوة؛ أجدبت أرضه يوماً فقام وتوضأ وصلى ودعا الله في شمس حارقة، فجمعت سحابة مطراً وغسلت بستانه دون سائر البساتين.

رابعاً: وفاته رضي الله عنه
عاش بالبصرة ينشر علم النبوة وسنتها للأمة حتى كان آخر من توفي من الصحابة في البصرة سنة 93 هـ وله من العمر نحو 103 أعوام، وأوصى أن يُدفن ومعه شعرة من شعر رسول الله ﷺ كانت عنده وعصية للنبي وضعت بين جنبيه وكفنه.

ماذا نتعلم من سيرة خادم الرسول أنس؟
1. الخلق النبوي الرفيع في التعامل مع الخدم والأبناء والرحمة بالصغار.
2. بركة دعاء الصالحين وأثره الملموس في الرزق والعمر والذرية.
3. حفظ السنة والتطبيق الدقيق لما كان يفعله النبي ﷺ في تفاصيل حياته.

