      "day": """هو جابر بن عبد الله بن عمرو بن حرام الأنصاري السلمي، كنيته «أبو عبد الله»، من كبار الصحابة المكثرين للحديث النبوي، وصاحب المواقف المشهودة مع رسول الله ﷺ.

أولاً: بيعة العقبة وبره بأخواته
حضر جابر بيعة العقبة الثانية وهو غلام يافع مع والده عبد الله بن عمرو بن حرام (الصحابي الجليل الذي كلمه الله كفاحاً بلا حجاب بعد استشهاده في أحد).
وعندما خرج أبوه إلى أحد قال له: «يا بني، إني لا أراني إلا مقتولاً في أول من يُقتل، وإني لا أترك بعدي أحداً أعز عليّ منك غير رسول الله، وإن عليّ ديناً فاقضِ عني دينِي، واستوصِ بأخواتك خيراً».
فاستشهد أبوه وترك له تسع أخوات ودَيناً كبيراً، فآثر جابر رعاية أخواته وتزوج امرأة ثيباً لتقوم عليهن وترعاهن، فدعا له النبي ﷺ وبرّك عليه.

ثانياً: معجزة الخندق وإطعام الجيش
في غزوة الخندق رأى جابر بطن النبي ﷺ مشدوداً بحجر من شدة الجوع، فذهب مسرعاً إلى زوجته وقال: «هل عندكِ شيء؟ فإني رأيتُ برسول الله خمصاً شديداً»، فذبحت بهيمة (عناقاً) وطحنت صاعاً من شعير، وذهب جابر سراً يسارّ النبي: «يا رسول الله، طُعيم لي فقم أنت ونفر معك»، فصاح النبي ﷺ في أهل الخندق كلهم: «يا أهل الخندق، إن جابراً قد صنع لكم سوراً فحيهلاً بكم!».
فجاء الجيش كله (ألف رجل)، وأمر النبي جابراً ألا ينزلوا القدر ولا يخبزوا العجين حتى يأتيهم، فبصق النبي في العجين ودعا بالبركة وبصق في البرمة، فجعل يغرف ويطعم الصحابة عشرة عشرة حتى شبع الجيش كله وفضل من الطعام، والقدر تغلي كما هي والعجين يخبز كما هو!

ثثالثاً: قصة الجمل وحنان النبوة
في إحدى الغزوات، كان جمل جابر ضعيفاً أعيى وتأخر به، فلحقه النبي ﷺ فنخس الجمل ودعا له، فوثب الجمل يسير في مقدمة الركاب بنشاط عجيب!
فقال له النبي: «أتبيعني جملك هذا يا جابر؟»، فماكسه النبي حتى اشتراه بأوقية ذهب، واستثنى جابر ركوبه حتى المدينة ليبلغ أهله، فلما وصلوا المدينة أتاه جابر بالجمل، فنقد له النبي ﷺ ثمنه كاملاً، ثم قال له برحمة وملاطفة: «خذ جملك وثمنه، فهو لك هدية!».

رابعاً: روايته لحجة الوداع ووفاته بالمدينة
انفرد جابر بن عبد الله برواية أطول وأدق حديث يصف حجة الوداع النبوية من البداية إلى النهاية بتفاصيلها الدقيقة؛ وهو الحديث المعتمد في صحيح مسلم الذي عليه مدار أحكام الحج عند الفقهاء.
وعاش طويلاً حتى كُف بصره، وصار له حلقة علم كبرى في المسجد النبوي، وتوفي سنة 78 هـ وله من العمر نحو 94 عاماً، وكان آخر من توفي من الصحابة الكرام في المدينة المنورة.

ماذا نتعلم من سيرة جابر بن عبد الله؟
1. البر بالآباء والوفاء بوصاياهم ورعاية الإخوة والأخوات وتقديمهم على حظوظ النفس.
2. عظمة البركة النبوية ومعجزات التكثير بحسن النية والإخلاص لله.
3. التثبت ونقل العلم الشرعي وسنة النبي ﷺ بدقة وأمانة بالغة للأجيال.

