أولاً: إسلامه والصدح بالقرآن بمكة
كان ابن مسعود يرعى غنماً لعقبة بن أبي معيط، فمر به النبي ﷺ وأبو بكر وهما مجهدان، فمسح النبي على ضرع شاة حائل لم ينزُ عليها فحل فدرت لبناً وسقاهما، فرأى ابن مسعود آية النبوة وقال: «علمني من هذا القول»، فمسح النبي على رأسه وقال: «إنك غُليم مُعلَّم»، فأسلم من فوره.
ولما اجتمع الصحابة يوماً بمكة وقالوا: «ما سمعت قريش هذا القرآن يجهر به قط، فمن رجل يسمعهموه؟»، تطوع ابن مسعود، ومضى إلى مقام إبراهيم في وضح النهار وقريش في أنديتها، فقرأ بصوت شجي باهر: ﴿الرَّحْمَنُ * عَلَّمَ الْقُرْآنَ * خَلَقَ الإِنسَانَ...﴾، فوثبت قريش تضربه في وجهه حتى أدموه، فعاد إلى الصحابة ووجهه يدمى وهو يقول: «ما كان أعداء الله أهون عليّ منهم الآن، ولئن شئتم لأغادينّهم بها غداً!».

ثانياً: ملازمته للنبي ونداthumb صوته بالقرآن
لازم النبي ﷺ حتى كان يلج على النبي في بيته ويخدمه؛ يحمل نعليه إذا مشى، ويمشي أمامه بالعصا، ويستره إذا اغتسل، ويوقظه إذا نام.
وكان ندي الصوت بالقرآن متقناً لأحكامه؛ قال له النبي ﷺ يوماً: «اقرأ عليّ القرآن»، فقال: «أأقرأ عليك وعليك أُنزل؟!»، قال: «إني أحب أن أسمعه من غيري»، فقرأ ابن مسعود سورة النساء حتى وصل إلى قوله تعالى: ﴿فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاء شَهِيدًا﴾، فقال النبي: «حسبك الآن»، فالتفت ابن مسعود فإذا عينا رسول الله ﷺ تذرفان دمعاً.

ثالثاً: ساقاه أثقل من جبل أحد
صعد ابن مسعود يوماً شجرة أراك يجتني منها سواكاً، وكان دقيق الساقين نحيف الجسم، فجعلت الريح تكفؤه فضحك القوم من دقة ساقيه، فقال رسول الله ﷺ زاجراً لهم ومبيناً موازين السماء: «مم تضحكون؟! والذي نفسي بيده، لَهما أثقلُ في الميزان يوم القيامة من جبل أُحد!».
وشهد بدراً وقتل أبا جهل بعد أن أثخنه ابنا عفراء، واحتز رأسه وجاء به إلى النبي ﷺ.

رابعاً: فقهه ووفاته
ولاه عمر بن الخطاب بيت مال الكوفة وتعليم أهلها، فبث العلم في العراق وأسس مدرسة الرأي والفقه التي سار عليها كبار التابعين وأبو حنيفة.
توفي رضي الله عنه في المدينة المنورة سنة 32 هـ وله من العمر نحو ستين عاماً، وصلى عليه عثمان بن عفان ودُفن بالبقيع.

ماذا نتعلم من سيرة عبد الله بن مسعود؟
1. أن قيمة الإنسان عند الله بإيمانه وعلمه وتقواه لا بحجم جسده ولا بظاهره الدنيوي.
2. الشغف بتعلم القرآن الكريم وتلاوته بخشوع وتدبر يفيض بالدموع.
3. التواضع في خدمة أهل الفضل والصالحين وملازمة مجالس العلم.

