أولاً: نشأته والدعوة النبوية المباركة
ولد ابن عباس في شعب أبي طالب قبل الهجرة بثلاث سنين، ولازم النبي ﷺ في أواخر حياته وهو صبي فطن ذكي.
وضمه رسول الله ﷺ يوماً إلى صدره الشريف ودعا له بدعوة كانت نوراً أضاء له مسالك العلم: «اللهم فقهه في الدين، وعلمه التأويل!».
وذات يوم كان رديفاً للنبي ﷺ على دابته، فقال له النبي الكلمات الذهبية الجامعة: «يا غلام، إني أعلمك كلمات: احفظ الله يحفظك، احفظ الله تجده تجاهك، إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله، واعلم أن الأمة لو اجتمعت على أن ينفعوك بشيء لم ينفعوك إلا بشيء قد كتبه الله لك، وإن اجتمعوا على أن يضروك بشيء لم يضروك إلا بشيء قد كتبه الله عليك، رُفعت الأقلام وجفت الصحف».

ثانياً: صبره العجيب في طلب العلم
بعد وفاة النبي ﷺ، انطلق ابن عباس الشاب يطلب الحديث من كبار الصحابة؛ فكان يذهب إلى باب الصحابي وقت القيلولة فيتوسد رداءه على بابه وتسفي الريح على وجهه من التراب منتظراً خروجه، فإذا خرج قال الصحابي: «يا ابن عم رسول الله، هلا أرسلت إليّ فآتيك؟»، فيقول ابن عباس بأدب طالب العلم: «لا، أنت أحق أن آتيك! العلم يُؤتى ولا يأتي».

ثالثاً: مجلس عمر بن الخطاب ومكانه بين الشيوخ
كان عمر بن الخطاب يدخل ابن عباس مع مشيخة بدر في ديوان الشورى، فوجد بعض الصحابة في أنفسهم وقالوا: «لِمَ تُدخل هذا الفتى معنا ولنا أبناء مثله؟»، فدعاهم عمر يوماً ليريهم علمه وسألهم عن قوله تعالى: ﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ﴾، فقال بعضهم: أمرنا أن نحمد الله ونستغفره إذا فتح علينا، وسكت بعضهم، فقال عمر: «أكذلك تقول يا ابن عباس؟»، قال: «لا يا أمير المؤمنين، هو أجل رسول الله ﷺ أعلمه الله له»، فقال عمر: «ما أعلم منها إلا ما تعلم!».

رابعاً: وفاته بالطائف
انتقل في أواخر حياته إلى الطائف وكُف بصره، وتوفي سنة 68 هـ وله من العمر نحو سبعين سنة، وصلى عليه محمد بن الحنفية، وقال حين أُدخل قبره: «اليوم مات رباني هذه الأمة!».

ماذا نتعلم من سيرة ترجمان القرآن؟
1. التواضع التام في طلب العلم والصبر على المشقة وتوقير المعلمين والعلماء.
2. حفظ وصايا التوحيد الخالص واليقين في قضاء الله وقدره واللجوء إليه وحده.
3. تدبر القرآن الكريم والغوص في معانيه وأسراره ودلالاته البلاغية.

