أولاً: نشأته وحرصه على الجهاد صبياً
هاجر مع أبيه وهو صبي صغير، وعُرض على النبي ﷺ يوم بدر وهو ابن ثلاث عشرة سنة فلم يُجزه، وعُرض يوم أحد وهو ابن أربع عشرة سنة فرده لصغره، حتى عُرض يوم الخندق وهو ابن خمس عشرة سنة فأجازه النبي للقتال، فشهد الخندق وبيعة الرضوان والمشاهد كلها.

ثانياً: رؤيا النار وقيام الليل
رأى عبد الله في نومه في عهد النبي ﷺ كأن ملكين أخذاه وذهبا به إلى النار، فإذا هي مطوية كطي البئر ولها قرنان وفيها رجال يعرفهم، فجعل يقول: «أعوذ بالله من النار!»، فلقيهما ملك آخر فقال له: «لم تُرَع»، فقصت أخته أم المؤمنين حفصة الرؤيا على النبي ﷺ، فقال النبي كلمته التربوية الخالدة: «نِعْمَ الرجلُ عبدُ الله، لو كان يصلي من الليل!».
قال نافع مولاه: «فكان عبد الله بعد ذلك لا ينام من الليل إلا قليلاً»، وظل محافظاً على قيام الليل حتى لقي ربه.

ثالثاً: كمال الاتباع للسنة النبوية
كان ابن عمر أحرص الناس على تتبع خطوات رسول الله ﷺ بدقة متناهية؛ فكان يصلي في كل مكان رأى النبي يصلي فيه، وينزل تحت كل شجرة استظل بها النبي في أسفاره ويصب في أصلها ماءً لئلا تجف محبةً لرسول الله.
وكان متورعاً شديد التحرز في الفتوى؛ إذا سُئل عما لا يتيقنه قال للسائل بهدوء: «لا أدري، اذهب إلى غيري»، وكان يرى أن الفتوى جسر إلى النار.

رابعاً: زهده واعتزال الفتن
عُرضت عليه الخلافة مراراً وأجمع الناس عليه في أوقات الشقاق، فرفض أن يقبلها إذا أُهريق في سبيله قطرة دم واحدة، وقال: «لا أقاتل في هذه الفتنة، ومن غلب صليتُ خلفه».
وكان من أكثر الصحابة صدقة وإعتاقاً للعبيد؛ كان إذا رأى من غلمانه وعبيده حُسن صلاة وعبادة أعتقه لوجه الله، فكان أصحابه يقولون له: «إنهم يخدعونك يا أبا عبد الرحمن بالتظاهر بالصلاة لتُعتقهم»، فكان يجيب بإيمان ناصع: «من خدعنا بالله انخدعنا له!».

خامساً: وفاته بمكة
توفي رضي الله عنه بمكة المكرمة سنة 73 هـ بعد أن أدى فريضة الحج وله من العمر نحو 84 عاماً، ودُفن بذي طوى، تاركاً إرثاً لا يبارى في الاتباع والورع.

ماذا نتعلم من سيرة عبد الله بن عمر؟
1. التمسك الدقيق بسنة النبي ﷺ في العبادات والسلوكيات اليومية.
2. المداومة على قيام الليل والمحافظة على صلاة الوتر والتهجد.
3. التورع في الفتوى والابتعاد التام عن الخوض في دماء المسلمين والفتن.

