أولاً: أول مولود في دار الهجرة
ولد عبد الله بقباء في شوال سنة 1 هـ، فكان أول مولود يولد للمهاجرين في المدينة المنورة بعد الهجرة.
وكان لمولده فرح عارم ملأ المدينة؛ إذ كانت اليهود تشيع أنها سحرت المسلمين فلا يولد لهم مولود ذكر لينقطع نسلهم، فخرجت به أمه أسماء إلى رسول الله ﷺ، فوضعه في حجره الشريف ومضغ تمرة وحنكه بها بريقه، فكان أول ما دخل جوف عبد الله ريق النبي ﷺ، ثم دعا له وبرّك عليه، وحمله أبو بكر وطاف به شوارع المدينة والمسلمون يكبرون تكبيراً هز يثرب.

ثانياً: بطولة مبكرة وفتح إفريقيا
نشأ على الفروسية والشجاعة والشهامة؛ شهد اليرموك غلاماً مرافقاً لأبيه.
وفي خلافة عثمان بن عفان، شارك في جيش فتح إفريقيا (تونس) سنة 27 هـ، وهناك حاصر المسلمون ملك الروم «جرجير» وجيشه العرمرم (120 ألفاً)، فرأى ابن الزبير الملك يقف وراء جيشه تشجعه جاريتان، فاخترق الصفوف بحركة فدائية خارقة ومعه ثلاثون فارساً، فقتل جرجير في قلب معسكره فتم النصر للمسلمين، وفُتحت سبيطلة وغنم المسلمون غنائم عظيمة.

ثالثاً: عبادته وخشوعه الأسطوري
كان عبد الله بن الزبير يُلقب بـ «حمامة المسجد» للزومه الطويل للصلاة في الحرمين؛ وكان يصوم الدهر ويسرد الصوم.
وكان إذا دخل في الصلاة خرج من الدنيا؛ فكان يسجد سجدة طويلة كأنه جذع شجرة ميت حتى تحط العصافير على ظهره تحسبه حائطاً أو خشبة! ووقع حجر من منجنيق الحصين بن نمير وهو يصلي في جوف الكعبة فطار جانب من ثوبه فما التفت ولا اهتز ولا خفف صلاته.

رابعاً: الخلافة واستشهاده بمكة
بويع له بالخلافة بعد وفاة يزيد بن معاوية سنة 64 هـ، ودانت له الحجاز واليمن والعراق وخراسان ومصر ومعظم الشام تسع سنين حكماً بالعدل والشورى.
ثم حاصره الحجاج بن يوسف الثقفي في مكة سنة 73 هـ، فدخل على أمه أسماء بنت أبي بكر وهي عجوز كفيفة ابنة مائة عام يشاورها في القتال بعد أن تفرق عنه أصحابه، فقالت له كلمتها الخالدة: «يا بني، إن كنت تعلم أنك على حق فامضِ له، فقد قُتل عليه أصحابك، ولا تمكّن من عنقك غلمان بني أمية! وإن كنت أردت الدنيا فبئس العبد أنت، أهلكت نفسك وأهلكت من قُتل معك!»، فقال: «جزاك الله خيراً يا أماه، هذا رأيي والله»، فقبل رأسها وخرج يقاتل بسيفه حتى استشهد رضي الله عنه عند الكعبة في جمادى الأولى سنة 73 هـ.

ماذا نتعلم من سيرة عبد الله بن الزبير؟
1. الخشوع التام في الصلاة واستشعار عظمة الله والوقوف بين يديه.
2. الثبات على المبدأ والشهامة المستمدة من الأمهات الصالحات المربيات.
3. الفروسية والشجاعة الفدائية في كسر شوكة الأعداء ونصرة راية الإسلام.

