      "day": """هو زيد بن ثابت بن الضحاك الأنصاري الخزرجي، كنيته «أبو سعيد» و«أبو خارجة»، كاتب وحي رسول الله ﷺ، وأفرض الصحابة (أعلمهم بقسمة المواريث والفرائض)، ورئيس لجنة جمع المصحف الشريف.

أولاً: ذكاؤه المبكر وتعلم اللغات
قُتل أبوه يوم بُعاث قبل الهجرة وهو صبي صغير، ولما هاجر النبي ﷺ إلى المدينة قُدم زيد وهو ابن إحدى عشرة سنة وقد حفظ سبع عشرة سورة من القرآن، فأعجب به النبي ﷺ وقال له: «يا زيد، تعلم لي كتاب يهود، فإني والله ما آمن يهود على كتابي».
فأكب زيد بعبقرية مذهلة على تعلم السريانية والعبرية، فحذقهما وأتقن قراءتهما وكتابتهما في خمسة عشر يوماً فقط! فصار يكتب للنبي رسائله إليهم ويقرأ له كتبهم إذا كتبوا إليه.

ثانياً: كاتب الوحي الأمين
اختصه النبي ﷺ بكتابة آيات القرآن الكريم فور نزولها في المدينة؛ فكان إذا نزل الوحي قال النبي: «ادعوا لي زيداً وليأتِ باللوح والدواة والكتف»، فيملي عليه الآيات ويكتبها بدقة بالغة ويراجعها النبي حرفاً حرفاً.

ثالثاً: جمع القرآن في عهد أبي بكر الصديق
بعد معركة اليمامة واستشهاد مئات من حفظة القرآن، أشار عمر على أبي بكر بجمع القرآن، فاختار أبو بكر زيد بن ثابت لهذه المهمة الجليلة وقال له: «إنك رجل شاب عاقل لا نتهمك، وقد كنت تكتب الوحي لرسول الله ﷺ، فتتبّع القرآن فاجمعه!».
قال زيد واصفاً ثقل المهمة: «فواللهِ لو كلفوني نقل جبل من الجبال ما كان أثقل عليّ مما أمرني به من جمع القرآن!».
فتتبع زيد القرآن يجمعه من العُسُب واللخاف والرقاع وصدور الرجال بمنهج توثيقي علمي صارم؛ لم يكن يقبل آية إلا بشاهدين عدلين يحفظانها ويثبتان كتابتها بين يدي النبي، حتى أتم جمعه في الصحف التي بقيت عند أبي بكر ثم عمر ثم حفصة.

رابعاً: نسخ المصحف الإمام في عهد عثمان
في عهد عثمان بن عفان، كلف عثمان زيداً مرة أخرى برئاسة اللجنة الرباعية لنسخ القرآن الكريم في المصاحف وتوحيد الأمة على رسم قريش، فقام بالمهمة بأعلى درجات الأمانة والإتقان، فدونت المصاحف العثمانية التي يقرأ بها المسلمون إلى قيام الساعة.

خامساً: وفاته وعلمه
كان ابن عباس رضي الله عنه مع جلالة قدره يأخذ بخطام ناقة زيد ويقول: «هكذا أُمرنا أن نفعل بعلمائنا وكبرائنا».
توفي زيد بالمدينة سنة 45 هـ، فقال ابن عباس عند قبره: «من سرّه أن يعلم كيف ذهاب العلم، فهكذا ذهاب العلم! والله لقد دُفن اليوم علمٌ كثير!».

ماذا نتعلم من سيرة زيد بن ثابت؟
1. توظيف الذكاء والقدرات اللغوية والعلمية في خدمة دين الله وتوثيق مصادره.
2. الدقة والمنهجية العلمية الصارمة في توثيق النصوص ونقل الأخبار.
3. توقير العلماء وأهل الفضل وإجلال من يحملون كتاب الله وسنته.

