أولاً: نشأته ومحبة النبي له
ولد أسامة بمكة في الإسلام، وكان النبي ﷺ يحبه حباً جماً؛ كان يضع الحسن بن علي على فخذه ويضع أسامة على فخذه الأخرى ثم يضمهما معاً ويقول: «اللهم إني أحبهما فأحبهما، وأحب من يحبهما!».

ثانياً: درس حرمة الدماء المعصومة
في سرية من السرايا، لاحق أسامة رجلاً مشركاً بالسيف، فلما أهوى عليه بالسيف قال الرجل: «لا إله إلا الله!»، فقتله أسامة متأولاً أنه قالها تعوذاً من القتل.
فلما رجعوا أخبر النبي ﷺ، فغضب النبي غضباً شديداً وجعل يكرر معاتباً إياه: «أقال لا إله إلا الله وقتلته يا أسامة؟! أقال لا إله إلا الله وقتلته؟! فكيف تصنع بلا إله إلا الله إذا جاءت يوم القيامة؟!».
قال أسامة: «يا رسول الله، استغفر لي، إنما قالها مخافة السلاح»، فقال النبي: «أفلا شققتَ عن قلبه حتى تعلم أقالها أم لا؟! فكيف تصنع بلا إله إلا الله إذا جاءت يوم القيامة؟!».
وظل النبي يكررها حتى قال أسامة: «فما زال يكررها حتى تمنيتُ لو أني لم أكن أسلمتُ إلا يومئذ!»؛ فكان هذا الدرس درساً خالداً لأسامة لم ينسه أبداً، فعصم سيفه من كل قطرة دم مسلم بعد ذلك طيلة حياته.

ثالثاً: قيادة جيش الشام وعمره 18 سنة
في صفر سنة 11 هـ قبل وفاة النبي بأيام، عقد النبي لأسامة بن زيد لواء جيش عظيم لغزو مؤتة ومشرف الشام والأخذ بثأر والده زيد والشهداء، وجعل في جيشه كبار المهاجرين والأنصار وأشراف قريش كعمر بن الخطاب وأبي عبيدة وسعد بن أبي وقاص.
ولما طعن بعض الناس في إمارته لصغر سنه (كان عمره نحو 18 أو 19 سنة)، صعد النبي ﷺ المنبر وخطب مغضباً فقال: «إن تطعنوا في إمارته فقد كنتم تطعنون في إمارة أبيه من قبل! وايمُ الله إن كان لخليقاً للإمارة، وإن كان لمن أحب الناس إليّ، وإن هذا لمن أحب الناس إليّ بعده!».
ولما توفي النبي ﷺ، أصر أبو بكر الصديق على إنفاذ جيش أسامة برغم ارتداد العرب وقال كلمته المأثورة: «والله لا أحل لواءً عقده رسول الله ﷺ ولو خطفتني الطير!»، فسار أسامة بالجيش وحقق نصراً مؤزراً وعاد سالماً غانماً.

رابعاً: وفاته رضي الله عنه
اعتزل أسامة الفتن السياسية تماماً تورعاً ووفاءً لدرس النبي ﷺ، وتوفي في الجرف قرب المدينة المنورة سنة 54 هـ وله من العمر نحو ستين عاماً، وصلى عليه المسلمون ودُفن بالبقيع.

ماذا نتعلم من سيرة أسامة بن زيد؟
1. تقديم الكفاءة والقدرة القيادية الشابة وتوليتها الثقة والمسؤولية.
2. حرمة دماء المسلمين العظمى ووجوب قبول ظاهر الإيمان وتوكيل السرائر إلى الله.
3. إنفاذ أوامر القيادة النبوية والتمسك بالثوابت حتى في أشد الأزمات والفتن.

