      "day": """هو خالد بن زيد بن كليب الأنصاري الخزرجي، كنيته «أبو أيوب الأنصاري»، الصحابي الجليل الذي فاز بشرف استضافة النبي ﷺ في رحلته التاريخية بالهجرة، وبطل الجهاد الذي عاش يطلب الشهادة حتى لقيها عند أسوار القسطنطينية.

أولاً: فوز داره ببروك ناقة النبوة
عندما دخل رسول الله ﷺ المدينة المنورة مهاجراً في ربيع الأول، تسابق زعماء الأنصار وكل منهم يمسك بخطام ناقته (القصواء) يرجو شرف نزوله عنده، فكان النبي يقول برفق: «دعوها فإنها مأمورة!».
فسارت الناقة حتى بركت في موضع المسجد النبوي، ثم قامت ومشت قليلاً ثم التفتت وعادت وبركت في موضعها الأول، فنزل النبي ﷺ، فبادر أبو أيوب الأنصاري فحمل رحل النبي ﷺ ومتاعه مسرعاً وأدخله في بيته، فقال النبي ﷺ بابتسامته الحانية: «المرء مع رحله!».

ثانياً: أدب المحبة والإجلال النبوي
نزل النبي ﷺ في الطابق السفلي من دار أبي أيوب رفقاً بزواره والوافدين عليه، فبات أبو أيوب وزوجته أم أيوب في الطابق العلوي قلقين وجلين؛ يقول أبو أيوب: «أنمشي فوق رأس رسول الله ﷺ ونحن في الظل وهو تحتنا؟!»، فانكسرت جرة ماء في الليل، فقام أبو أيوب وزوجته بقطيفة لهما ينشفان بها الماء خشية أن يقطر على رسول الله ماء يؤذيه!
وفي الصباح نزل أبو أيوب يناشد النبي أن ينتقل للطابق العلوي، فانتقل النبي إكراماً لأبي أيوب.
وكان يصنع للنبي طعامه، فإذا رُد الإناء بحث أبو أيوب عن موضع أصابع النبي ﷺ فيأكل منه يبتغي البركة.

ثالثاً: الجهاد المستمر وتفسير آية التهلكة
شهد أبو أيوب بدراً وأحداً والمشاهد كلها، ولم يتخلف عن غزوة للمسلمين قط في عهد النبوة ولا في عهد الخلفاء الراشدين.
وفي غزوة الروم بالقسطنطينية، حمل رجل من المسلمين بمفرده على صف الروم، فقال الناس: «ألقى بيده إلى التهلكة!»، فقام أبو أيوب الأنصاري فصحح الفهم وقال: «أيها الناس، إنكم تتأولون هذه الآية على غير وجهها؛ إنما نزلت هذه الآية فينا معشر الأنصار؛ لما أعز الله الإسلام وكثر ناصروه، قلنا سراً فيما بيننا: لو أقمنا في أموالنا وأصلحناها، فأنزل الله تعالى رداً علينا: ﴿وَأَنفِقُواْ فِي سَبِيلِ اللَّهِ وَلاَ تُلْقُواْ بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾؛ فالتهلكة كانت الإقامة في الأموال وترك الجهاد!».

رابعاً: استشهاده ودفنه عند أسوار القسطنطينية
في سنة 52 هـ في خلافة معاوية، خرج أبو أيوب في جيش يزيد بن معاوية لغزو القسطنطينية وهو شيخ جاوز الثمانين من عمره، فلما أثقله المرض واحتضر قال لقائد الجيش: «إذا أنا مت، فاحملوني، فإذا صاففتم العدو فادفنوني تحت أقدامكم عند أقصى موضع في أرض العدو تقفون عليه!».
ففعلوا به ذلك، وحملوه حتى دفنوه ملاصقاً لأسوار القسطنطينية (إسطنبول الحالية)، محققاً بشارة النبي ﷺ في نيل أجر الرباط في سبيل الله.

ماذا نتعلم من سيرة أبي أيوب الأنصاري؟
1. إكرام الضيف ومحبة النبي ﷺ والتأدب العالي مع مقامه الشريف.
2. التضحية بالنفس والمال والاستمرار في نصرة الدين والجهاد حتى أرذل العمر.
3. الفهم الدقيق لآيات القرآن الكريم ورد المفاهيم الخاطئة إلى مراد الشريعة.

المصادر والمراجع المعتمدة:
