      "day": """هي خديجة بنت خويلد بن أسد بن عبد العزى الأسدية القرشية، كنيتها «أم القاسم»، الطاهرة في الجاهلية، وأول أمهات المؤمنين، وأول من آمن برسول الله ﷺ وصدقه على الإطلاق.

أولاً: فضلها ومكانتها قبل البعثة
كانت خديجة سيدة نساء قريش نسباً وشرفاً ومالاً وعقلاً؛ تاجرت بأموالها واختارت محمداً ﷺ ليخرج في تجارتها إلى الشام لما بلغها من صدقه وأمانته وعفته.
ولما رجع ميسرة خادمها وأخبرها بما رأى من بركته وأمانته وخُلقه العظيم، رغبت في الزواج منه فتزوجها رسول الله ﷺ وهو ابن خمس وعشرين سنة وهي في سن الأربعين على المشهور، وكانت له نعم الزوجة الصالحة؛ رزق منها جميع أبنائه وبناته عدا إبراهيم.

ثانياً: تثبيت النبوة في غار حراء
لما نزل الوحي على النبي ﷺ في غار حراء ورجع إلى بيته ترجف بوادره ويقول: «زملوني زملوني.. لقد خشيتُ على نفسي!»، أظهرت خديجة أعظم ثبات عقلي وإيماني في التاريخ؛ فقالت كلماتها الخالدة بلسان اليقين: «كلا والله، ما يخزيك الله أبداً! إنك لتصل الرحم، وتحمل الكل، وتكسب المعدوم، وتقري الضيف، وتعين على نوائب الحق!».
ثم انطلقت به فوراً إلى ابن عمها ورقة بن نوفل وكان حبراً عالماً بالتوراة والإنجيل، فثبتهما وأخبرهما أن هذا هو «الناموس» الذي نزل على موسى عليه السلام.

ثالثاً: البذل العظيم وسلام رب العالمين
كانت خديجة وزيرة الصدق للنبي ﷺ؛ تواسيه بمالها إذا كذبه الناس، وتخفف عنه أثقال الحزن، وصبرت معه في حصار شِعب أبي طالب ثلاث سنوات عجاف وهي سيدة قريش المنعمة.
وثبت في الصحيحين أن جبريل عليه السلام أتى النبي ﷺ يوماً فقال: «يا رسول الله، هذه خديجة قد أتتك معها إناء فيه إدام أو طعام أو شراب، فإذا هي أتتك فاقرأ عليها السلام من ربها ومني، وبشرها ببيت في الجنة من قصب، لا صخب فيه ولا نصب!».

رابعاً: وفاتها ووفاء النبي الدائم لها
توفيت رضي الله عنها بمكة في رمضان قبل الهجرة بثلاث سنين (عام الحزن)، ودفنت بالحجون، ونزل النبي ﷺ في قبرها ودموعه تبلل ثراها.
وظل النبي ﷺ طيلة حياته يذكر فضلها ويبر صواحبها، حتى غارت عائشة وقالت يوماً: «ما تذكر من عجوز أبدلك الله خيراً منها؟!»، فغضب النبي ﷺ غضباً شديداً وقال مبيناً وفاءه العظيم: «والله ما أبدلني الله خيراً منها! آمنتْ بي إذ كفر بي الناس، وصدقتني إذ كذبني الناس، وواستني بمالها إذ حرمني الناس، ورزقني الله ولدها إذ حرمني أولاد النساء!».

ماذا نتعلم من سيرة السيدة خديجة؟
1. دور الزوجة الصالحة في تثبيت الزوج ومساندته النفسية والمادية في الأزمات الكبرى.
2. عظمة الوفاء النبوي وحفظ العهد لمن أحسن وصبر وبذل.
3. كرم الله العظيم لمن بذل في سبيله؛ جزاها بيتاً في الجنة هادئاً كما أمنت النبي من الصخب والنصب.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب بدء الوحي (حديث 3)، وكتاب فضائل الصحابة، باب تزويج النبي خديجة وفضلها (حديث 3815، 3818، 3821).
• صحيح مسلم: كتاب فضائل الصحابة، باب فضائل خديجة أم المؤمنين (حديث 2435، 2437).
• سيرة ابن هشام، والبداية والنهاية لابن كثير (ترجمة خديجة بنت خويلد)."""
