      "additionalInfo": "سئل النبي ﷺ: من أحب الناس إليك؟ قال: «عائشة»، قيل: من الرجال؟ قال: «أبوها».",
      "day": """هي عائشة بنت أبي بكر الصديق التيمية القرشية، كنيتها «أم عبد الله» (كنّاها النبي بابن أختها عبد الله بن الزبير)، لُقبت بـ «الصديقة بنت الصديق» و«الحميراء» و«حبيبة رسول الله ﷺ».

أولاً: زواجها ومحبة النبي الاستثنائية لها
رأى النبي ﷺ صورتها في المنام مرتين في سرقة من حرير وجبريل يقول: «هذه امرأتك»، فتزوجها بمكة وبنى بها في شوال بالمدينة المنورة بعد غزوة بدر، وكانت أحب أزواجه إليه؛ سئل رسول الله ﷺ علانية: «من أحب الناس إليك؟»، فقال دون تردد: «عائشة!»، فقيل له: «من الرجال؟»، قال: «أبوها!».

ثانياً: حادثة الإفك وبراءة السماء
في غزوة بني المصطلق، وقعت حادثة الإفك المؤلمة؛ حيث أشاع المنافقون فرية كاذبة باطلة لتمزيق بيت النبوة، فمرضت عائشة شهراً لا تعلم شيئاً وهي تبكي وتصلي.
فلما علمت بكت حتى ظنت أن البكاء فالق كبدها، وقالت لأبويها وللنبي بثقة ويقين: «والله لقد علمتُ لقد سمعتم هذا الحديث حتى استقر في نفوسكم وصدقتم به، فلئن قلتُ لكم إني بريئة والله يعلم أني بريئة لا تصدقوني، ولئن اعترفتُ لكم بأمر والله يعلم أني منه بريئة لتصدقني! فوالله لا أجد لي ولكم مثلاً إلا أبا يوسف حين قال: ﴿فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَى مَا تَصِفُونَ﴾».
فما نزل النبي من مكانه حتى غشيه الوحي وسُري عنه وهو يضحك ويقول: «أبشري يا عائشة، أما الله فقد برأكِ!»، ونزلت عشر آيات كاملات في سورة النور تُتلى في المحاريب إلى قيام الساعة براءةً لطهرها ونقاء عرضها.

ثالثاً: علمها وفقهها الذي لا يبارى
كانت رضي الله عنها أفقر نساء الأرض مالاً وأغناهن علماً؛ حفظت القرآن وروت أكثر من ألفين ومائتي حديث عن النبي ﷺ.
وكان كبار الصحابة كأبي موسى الأشعري وابن عمر إذا أشكل عليهم أمر من الفقه وفتاوى المواريث والطب والشعر جاؤوا إلى عائشة فيجدون عندها منه علماً شافياً.
وكانت كثيرة الصدقة والزهد؛ أتاها مائة ألف درهم من معاوية ففرقتها على الفقراء في يوم واحد وهي صائمة وثوبها مرقع، فقالت لها خادمتها: «أما استطعتِ أن تشتري بدرهم لحماً تفطرين عليه؟!»، فقالت: «لو ذكرتِني لفعلت!».

رابعاً: وفاتها ودفنها بالبقيع
مات النبي ﷺ في حجرتها بين سحرها ونحرها ودُفن في أرض بيتها.
وعاشت بعده تنشر العلم وتفتي المسلمين حتى توفيت في المدينة ليلة الثلاثاء 17 رمضان سنة 58 هـ ودفنت بالبقيع بعد صلاة الوتر، وصلى عليها أبو هريرة في موكب جنائزي مهيب لم تشهد المدينة مثله.

ماذا نتعلم من سيرة الصديقة عائشة؟
1. مكانة المرأة العظيمة في العلم الشرعي والتعليم والفتوى والريادة الفكرية.
2. الصبر المطلق واللجوء إلى الله عند التعرض للظلم والافتراء والشائعات.
3. الجود والإنفاق الخفي ونسيان حظوظ النفس في سبيل سد حاجات المساكين.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب فضائل الصحابة، باب فضل عائشة رضي الله عنها (حديث 3768، 3770)، وحديث الإفك الطويل (حديث 4750).
• صحيح مسلم: كتاب فضائل الصحابة، باب فضائل عائشة أم المؤمنين (حديث 2442، 2447).
• سير أعلام النبلاء للذهبي (ترجمة عائشة أم المؤمنين)."""
