      "day": """هي حفصة بنت عمر بن الخطاب العدوية القرشية، كنيتها «أم المؤمنين»، ابنة الفاروق عمر، وحارسة النسخة الأولى المجمعة للمصحف الشريف.

أولاً: زواجها المبارك وبشارة جبريل
تزوجت في مكة خنيس بن حذافة السهمي، فهاجرا معاً إلى المدينة المنورة، وشهد خنيس بدراً وأحداً وجُرح بأحد جراحاً بليغة استشهد على إثرها.
فعرض عمر ابنته الشابة الأرملة على عثمان وأبي بكر رضي الله عنهما، فسكتا لعلمهما بسر النبي، ثم خطبها رسول الله ﷺ وتزوجها في شعبان سنة 3 هـ بعد غزوة بدر، ففرح عمر فرحاً شديداً بمصاهرة النبي ﷺ.
وثبت في السنن والمستدرك بسند صحيح أن النبي ﷺ طلقها تطليقة بأمر عارض، فنزل جبريل عليه السلام مسرعاً من السماء وقال للنبي: «راجع حفصة! فإنها صوامةٌ قوامة، وإنها زوجتك في الجنة!».

ثانياً: حراسة أول مصحف في الإسلام
نالت حفصة رضي الله عنها شرفاً تاريخياً فريداً؛ إذ اختارها أبو بكر وعمر لتكون الحافظة المؤتمنة على «الصحف الأولى المجمعة للقرآن الكريم» بعد وفاة أبي بكر ثم استشهاد عمر.
فظلت هذه النسخة الأم محفوظة بعناية فائقة في حجرتها، حتى طلبها أمير المؤمنين عثمان بن عفان لنسخ المصاحف وتوحيد قراءة الأمة، ثم ردها إليها وفاءً بأمانتها ومكانتها.

ثالثاً: عبادتها ووفاتها
كانت رضي الله عنها عابدة متبتلة، تسرد الصيام وتقوم الليل، وروت عن النبي ﷺ وعن أبيها الفاروق أحاديث جليلة في العبادات وأحكام الحج.
توفيت رضي الله عنها في المدينة المنورة في شعبان سنة 45 هـ في خلافة معاوية ودفنت في بقيع الغرقد إلى جانب أمهات المؤمنين.

ماذا نتعلم من سيرة حفصة أم المؤمنين؟
1. فضل الصيام وقيام الليل وأثرهما العظيم في نيل ولاية الله ومحبته.
2. الأمانة العلمية الفائقة في صيانة نصوص الوحي وخدمة المصحف الشريف.
3. حرص الآباء الصالحين على تزويج بناتهم من أهل الدين والصلاح.

المصادر والمراجع المعتمدة:
• سنن النسائي: كتاب الطلاق (حديث 3557 وصححه الألباني: راجع حفصة فإنها صوامة قوامة).
• صحيح البخاري: كتاب فضائل القرآن، باب جمع القرآن (حديث 4987: صحف القرآن عند حفصة).
• الطبقات الكبرى لابن سعد، وسير أعلام النبلاء للذهبي (ترجمة حفصة أم المؤمنين)."""
