أولاً: ملحمة الهجرة وصبر المحتسبين
هاجرت مع زوجها الصحابي الجليل أبي سلمة بن عبد الأسد إلى الحبشة، ثم قررا الهجرة إلى المدينة المنورة، فمنعها بنو المغيرة وانتزعوا منها ابنها سلمة حتى تخلعت يده، وهاجر زوجها بمفرده؛ فظلت أم سلمة سنة كاملة تخرج كل غداة إلى الأبطح بمكة تبكي حتى يمسي المساء فراقاً لزوجها وابنها، حتى رق لها أحد أقاربها فردوا إليها ابنها فهاجرت وحدها مع طفلها قاطعة مئات الكيلومترات في الصحراء حتى أجارها عثمان بن طلحة برؤية وشهامة عربية وأوصلها للمدينة.

ثانياً: الدعاء المأثور ومصاهرة النبوة
أصيب زوجها أبو سلمة بأحد ثم مات، فاسترجعت وتذكرت وصية النبي ﷺ: «ما من مسلم تصيبه مصيبة فيقول: إنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي وأخلف لي خيراً منها، إلا أخلف الله له خيراً منها»، فقالت في نفسها: «ومن خير من أبي سلمة أول بيت هاجر في الإسلام؟!».
لكنها دعت بالدعاء ثقة بوعد الله، فما انقضت عدتها حتى خطبها رسول الله ﷺ وتزوجها في شوال سنة 4 هـ، فقالت: «فأخلف الله لي خيراً من أبي سلمة.. رسولَ الله ﷺ!».

ثالثاً: حكمة الحديبية التاريخية
في صلح الحديبية سنة 6 هـ، لما أمر النبي ﷺ الصحابة بالتحلل من إحرامهم والنحر والحلق كررها ثلاثاً فلم يقم أحد لهول صدمة شروط الصلح الظاهرية، فدخل النبي خيمته مهموماً عند أم سلمة وأخبرها، فقالت له برأي سديد وحكمة نادرة: «يا رسول الله، أتحب ذلك؟ اخرج ثم لا تكلم أحداً منهم كلمة حتى تنحر بُدْنَك وتدعو حالقك فيحلقك!».
فأخذ النبي ﷺ بمشورتها وخرج أمامهم ونحر وحلق، فلما رأى الصحابة ذلك قاموا يبتدرون فنحروا وحلقوا، ففرّج الله بها كربة عظيمة عن الأمة ببركة مشورتها.

رابعاً: وفاتها
كانت رضي الله عنها فقيهة جليلة روت 378 حديثاً، وعاشت حتى أدركت مقتل الحسين بن علي فبكت عليه حتى غُشي عليها، وتوفيت سنة 61 هـ ودفنت بالبقيع وكانت آخر أمهات المؤمنين وفاةً.

ماذا نتعلم من سيرة أم سلمة؟
1. فضل الاسترجاع والدعاء النبوي عند نزول المصائب وحتمية إخلاف الله بخير منها.
2. رجاحة عقل المرأة المسلمة وجواز مشاورتها والأخذ برأيها في أعظم الشؤون السياسية والمصيرية.
3. التضحية والصبر الشجاع على هجر الأوطان والأهل فراراً بالعقيدة.

المصادر والمراجع المعتمدة:
• صحيح مسلم: كتاب الجنائز، باب ما يقال عند المصيبة (حديث 918: قصة دعاء أبي سلمة وزواج النبي).
• صحيح البخاري: كتاب الشروط، باب الشروط في الجهاد والمصالحة (حديث 2731، 2732: مشورة أم سلمة في الحديبية).
• سيرة ابن هشام، والبداية والنهاية لابن كثير (ترجمة أم سلمة أم المؤمنين)."""
