      "day": """هي سودة بنت زمعة بن قيس العامرية القرشية، كنيتها «أم المؤمنين»، أول امرأة تزوجها رسول الله ﷺ بمكة بعد وفاة السيدة خديجة رضي الله عنها، ضربت أروع الأمثلة في الإيثار والمحبة النبوية.

أولاً: هجرتها إلى الحبشة وزواجها المبارك
أسلمت سودة قديماً بمكة مع زوجها السكران بن عمرو وهاجرا معاً إلى الحبشة فراراً بدينهما، ثم رجعا إلى مكة فتوفي زوجها وتركها وحيدة بلا معيل.
فأرسل النبي ﷺ خولة بنت حكيم تخطبها له تكريماً لجهادها وجبراً لخاطرها ورعاية لأولادها، فتزوجها النبي بمكة في شوال قبل الهجرة، فقامت على بيت النبي وبناته بكل رفق وتفانٍ في أشد أوقات المحنة المكية.

ثانياً: خلق الإيثار العظيم
لما كبرت في السن وخشيت أن يفارقها النبي ﷺ لثقل حركتها، ورغبت أن تبقى زوجة له في الجنة، قالت للنبي بمحبة مؤمنة صادقة وإيثار لا نظير له: «يا رسول الله، قد جعلتُ يومي لعائشة، فأنت مني في حل»، فنزل في شأنها قوله تعالى: ﴿وَإِنِ امْرَأَةٌ خَافَتْ مِن بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلا جُنَاحَ عَلَيْهِمَا أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ﴾.
وكانت عائشة رضي الله عنها تعجب من كمالها ونبلها وتقول: «ما رأيتُ امرأةً أحبَّ إليّ أن أكون في مِسلاخها (أي مثل سيرتها وخلقها) من سودة بنت زمعة!».

ثالثاً: جودها ووفاتها
كانت رضي الله عنها تحب الصدقة حباً جماً؛ أرسل إليها عمر بن الخطاب في خلافته بجراب فيه دراهم، فقالت: «ما هذا؟ كأنه تمر!»، ففرقتها كلها في الحين على المساكين ولم تبقِ منها درهماً واحداً.
توفيت رضي الله عنها في المدينة المنورة في أواخر خلافة عمر بن الخطاب سنة 54 هـ على الراجح، ودُفنت بالبقيع.

ماذا نتعلم من سيرة سودة بنت زمعة؟
1. خلق الإيثار وتقديم محبة الآخرين والتعفف عن حظوظ النفس ابتغاء الدار الآخرة.
2. الوفاء النبوي لمن صبرت وهاجرت ورعت بيت النبوة في بداياته.
3. الجود والإنفاق الفوري والزهد في ادخار الأموال.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب النكاح، باب المرأة تهب يومها من زوجها لضرتها (حديث 5212).
• صحيح مسلم: كتاب الرضاع، باب جواز هبتها نوبتها لضرتها (حديث 1463).
• الطبقات الكبرى لابن سعد، وسير أعلام النبلاء للذهبي (ترجمة سودة بنت زمعة)."""
