فتزوجها رسول الله ﷺ في رمضان سنة 3 هـ بعد استشهاد زوجها، إكراماً لها ومكافأة لإحسانها الطويل إلى المساكين، وتأليفاً لقلوب بني هلال ودخولاً في مصاهرتهم.

ثانياً: صفة أم المساكين
لم يميزها لقب عبر التاريخ كما ميزها هذا الوصف العظيم: «أم المساكين»؛ فكان بيتها مأوى للضعفاء والمحتاجين، تفرغ وقتها لإعداد الطعام لهم وسد حاجاتهم وكسوتهم، حتى صارت عَلماً في الجود والرحمة.

ثالثاً: وفاتها السريعة وصلاة النبي عليها
لم تمكث زينب بنت خزيمة في بيت النبوة إلا نحو شهرين أو ثلاثة أشهر، ثم مرضت وتوفيت في ربيع الآخر سنة 4 هـ وهي في ريعان شبابها وله من العمر نحو ثلاثين سنة.
وحزن عليها النبي ﷺ حزناً بالغاً، وصلى عليها بنفسه ونزل في قبرها ودُفنت في بقيع الغرقد، وكانت أول من دُفن بالبقيع من أمهات المؤمنين، والوحيدة التي ماتت في المدينة المنورة في حياة النبي ﷺ بعد خديجة التي ماتت بمكة.

ماذا نتعلم من سيرة زينب بنت خزيمة؟
1. أن أثر الإحسان وإطعام المساكين يخلد اسم صاحبه ويبقى في موازين الحسنات مهما قصرت الحياة.
2. سرعة انقضاء الدنيا وأن العبرة بحسن الخاتمة وصلاح العمل.
3. التكافل الاجتماعي وإيواء الأرامل وأسر الشهداء وإكرامهم.

