أولاً: إبطال التبني والزواج القرآني الخالد
كانت زينب زوجة لزيد بن حارثة (الذي كان يُدعى زيد بن محمد بالتبني في الجاهلية)، فلما وقع الشقاق بينهما وطلقها زيد، أمر الله نبيه أن يتزوجها لإبطال عادة التبني الجاهلية وإباحة زواج زوجة الدعيّ؛ ونزل القرآن الكريم صريحاً: ﴿فَلَمَّا قَضَى زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَاكَهَا لِكَيْ لا يَكُونَ عَلَى الْمُؤْمِنِينَ حَرَجٌ فِي أَزْوَاجِ أَدْعِيَائِهِمْ إِذَا قَضَوْا مِنْهُنَّ وَطَرًا وَكَانَ أَمْرُ اللَّهِ مَفْعُولاً﴾.
فكانت زينب تفخر على سائر أمهات المؤمنين بإيمان واعتزاز قائلة: «زوجكن أهاليكن، وزوجني الله من فوق سبع سماوات!».

ثانياً: أطول أزواج النبي يداً بالصدقة
سأل أزواج النبي ﷺ رسول الله يوماً: «أيتنا أسرع بك لحوقاً بعد موتك؟»، فقال ﷺ: «أسرعكن لحوقاً بي أطولكن يداً!».
فكان أزواجه يقسن أيديهن بالقصبة في الجدار يظنن أنه طول اليد الحسي، فلما توفيت زينب أولهن علموا أن النبي ﷺ عنى طول اليد بالصدقة والبذل؛ إذ كانت زينب امرأة صناع اليدين، تدبغ الجلود وتخرزها وتبيعها ثم تتصدق بثمنها كله في سبيل الله للمساكين.

ثالثاً: ورعها التام ووفاتها
عندما وقعت حادثة الإفك سأل النبي ﷺ زينب عن عائشة (وكانت تنافسها في المكانة عند النبي)، فقالت زينب بورع وتقوى تسجل بمداد الذهب: «يا رسول الله، أحمي سمعي وبصري! والله ما علمتُ عليها إلا خيراً!»، فقالت عائشة مثنية عليها: «وهي التي كانت تساميني من أزواج النبي ﷺ فعصمها الله بالورع!».
توفيت رضي الله عنها في المدينة المنورة سنة 20 هـ في خلافة عمر ودفنت بالبقيع، وكانت أول أمهات المؤمنين وفاة بعد النبي ﷺ مصداقاً لنبوءته.

ماذا نتعلم من سيرة زينب بنت جحش؟
1. التسليم المطلق لأحكام الله وتشريعاته وكسر العادات الجاهلية الباطلة بالقرآن.
2. شرف العمل اليدوي للمرأة والإنفاق الخيري التام في وجوه البر والمساكين.
3. الورع وإنصاف الخصوم وقول الحق عند الشهادة دون تأثر بالمنافسة الدنيوية.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب التوحيد، باب وكان عرشه على الماء (حديث 7420: زوجني الله من فوق سبع سماوات)، وكتاب الشهادات (حديث 2661).
• صحيح مسلم: كتاب فضائل الصحابة، باب فضائل زينب أم المؤمنين وأسرعكن لحوقاً بي (حديث 2452، 2454).
• سير أعلام النبلاء للذهبي (ترجمة زينب بنت جحش)."""
