      "day": """هي جويرية بنت الحارث بن أبي ضرار الخزاعية، كنيتها «أم المؤمنين»، ابنة سيد بني المصطلق وزعيمهم، الصحابية الجليلة العابدة التي كانت أعظم امرأة بركة على قومها في تاريخ الإسلام.

أولاً: غزوة بني المصطلق وحرية قومها
وقعت جويرية في السبي بعد غزوة المريسيع (بني المصطلق) سنة 5 هـ، وكانت امرأة بارعة الجمال والعقل، فكاتبت ثابت بن قيس على فدائها، ثم جاءت رسول الله ﷺ تستعينه في كتابتها.
فعرض عليها النبي ﷺ عرضاً كريماً نبيلاً: «هل لك في خير من ذلك؟»، قالت: «وما هو يا رسول الله؟»، قال: «أقضي كتابتك وأتزوجكِ»، فرضيت وأسلمت لله.
فلما سمع الصحابة بخبر الزواج قالوا بإجلال: «أصهار رسول الله ﷺ يُسترقون؟! أطلقوا ما في أيديكم!»، فأعتق المسلمون مائة أهل بيت من بني المصطلق إكراماً لمصاهرة النبي ﷺ؛ فقالت عائشة رضي الله عنها كلمتها المشهورة: «فما رأينا امرأةً قط كانت أعظمَ بركةً على قومها منها؛ أُعتق في سببها مائة أهل بيت من بني المصطلق!».

ثانياً: عابدة الضحى والكلمات الأربع المباركة
كانت جويرية رضي الله عنها محبة للذكر والاعتكاف في مصلاها؛ خرج النبي ﷺ من عندها بكرة بعد صلاة الصبح وهي في مصلاها تذكر الله، ثم رجع بعد أن أضحى وهي ما زالت جالسة في موضعها تسبح، فقال لها ﷺ: «ما زلتِ على الحال التي فارقتكِ عليها؟!»، قالت: «نعم»، فقال النبي ﷺ: «لقد قلتُ بعدكِ أربعَ كلمات ثلاثَ مرات، لو وُزنت بما قلتِ منذ اليوم لوزنتهن:
«سُبْحَانَ اللهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ»!».
فصارت هذه الكلمات الأربع كنزاً نبوياً يومياً لكل مسلم يرجو مضاعفة أجور الذكر والتسبيح.

ثالثاً: وفاتها
عاشت رضي الله عنها بالمدينة عابدة ذاكرة شاكرة حتى توفيت في ربيع الأول سنة 56 هـ في خلافة معاوية بن أبي سفيان وله من العمر نحو خمس وستين سنة، وصلى عليها مروان بن الحكم ودفنت بالبقيع.

ماذا نتعلم من سيرة جويرية أم المؤمنين؟
1. توظيف المصاهرة والعلاقات الاجتماعية لإشاعة السلام والحرية وتأليف القلوب للدين.
2. فضل الذكر النبوي المأثور واستثمار جوامع الكلم التي تعدل الساعات الطوال في الميزان.
3. المداومة على الجلوس في المصلى بعد صلاة الصبح لذكر الله والاستغفار.

المصادر والمراجع المعتمدة:
• صحيح مسلم: كتاب الذكر والدعاء والتوبة، باب التسبيح أول النهار وعند النوم (حديث 2726: حديث جويرية في الذكر).
• سنن أبي داود: كتاب العتق، باب في بيع المكاتب (حديث 3931: قصة زواجها وإعتاق قومها).
• سيرة ابن هشام، وسير أعلام النبلاء للذهبي (ترجمة جويرية بنت الحارث)."""
