      "day": """هي رملة بنت أبي سفيان صخر بن حرب الأموية القرشية، كنيتها واشتهارها «أم حبيبة»، ابنة زعيم قريش قبل إسلامه، إحدى الصابرات المهاجرات اللاتي قدمن أعظم نماذج الثبات على العقيدة.

أولاً: هجرة الحبشة وابتلاء الغربة
أسلمت رملة بمكة قديماً مع زوجها عبيد الله بن جحش، وعصت أباها أبا سفيان (سيد بطحاء مكة)، وهاجرت مع زوجها إلى الحبشة في الهجرة الثانية وأنجبت ابنتها حبيبة.
وهناك ابتليت بابتلاء مؤلم؛ إذ تنصر زوجها وفارق الإسلام ومات هناك، بينما ثبتت أم حبيبة كالجبل الأشم على دينها متمسكة بإسلامها وحيدة في ديار الغربة القاصية ترعى طفلتها الصغيرة.

ثانياً: خطبة السماء ومكرمة النجاشي
لما علم النبي ﷺ بصبرها وثباتها في الحبشة بعد وفاة زوجها، أرسل الصحابي عمرو بن أمية الضمري بكتاب إلى النجاشي ملك الحبشة يخطبها للنبي ﷺ ويعقد له عليها.
فأرسل النجاشي جاريته أبرهة تبشرها بالخبر، ففرحت فرحاً غمر قلبها وخلعت حليها وأعطتها للجارية بشارة، ووكلت ابن عمها خالد بن سعيد بن العاص بالعقد، فأقام النجاشي وليمة عظيمة في قصره وأصدقها من عنده أربعمائة دينار ذهبي نيابة عن النبي ﷺ، وجهزها بأفخر الثياب وحملها في سفينتين إلى المدينة المنورة سنة 7 هـ.

ثالثاً: غيرتها العقدية على فراش النبوة
قبل فتح مكة، جاء أبوها أبو سفيان إلى المدينة المنورة يرجو تجديد الهدنة وتوسيع حلف قريش، فدخل على ابنته أم حبيبة في حجرتها، وأراد أن يجلس على فراش رسول الله ﷺ، فبادرت وطوت الفراش ومنعته من الجلوس عليه!
فقال متعجباً: «يا بنية، أرغبتِ بهذا الفراش عني أم رغبتِ بي عنه؟»، فأجابت بصرامة العقيدة النقية: «بل هو فراش رسول الله ﷺ، وأنت رجل مشرك نجس، فلم أحب أن تجلس على فراش رسول الله!».

رابعاً: وفاتها
عاشت رضي الله عنها عابدة محتسبة، ولما حضرتها الوفاة دعت عائشة وأم سلمة واستحلتهما وقالت: «قد كان يكون بيننا ما يكون بين الضرائر، فغفر الله لي ولكما»، فقالت عائشة: «غفر الله لكِ وحللكِ»، فقالت: «سررتِني سركِ الله».
توفيت رضي الله عنها في المدينة المنورة سنة 44 هـ على الراجح [يحتاج تحديد سنتها الدقيقة إلى تدقيق لاختلاف الروايات]، ودُفنت بالبقيع.

ماذا نتعلم من سيرة أم حبيبة؟
1. الثبات الراسخ على الدين الحق في الغربة وتحمل فقد الأهل والزوج في سبيل الله.
2. تقديم رابطة العقيدة ومحبة رسول الله ﷺ على وشائج النسب والأبوة عند التعارض.
3. التحلل وطلب العفو من الأقران وتصفية القلوب قبل لقاء الله تعالى.

المصادر والمراجع المعتمدة:
