      "day": """هي صفية بنت حُيَيّ بن أخطب من بني النضير، كنيتها «أم المؤمنين»، ينتهي نسبها الشريف إلى نبي الله هارون بن عمران أخي موسى كليم الله عليهما السلام، جمعت بين الحسب والجمال والحلم والصدق.

أولاً: فتح خيبر ومصاهرة النبوة
كانت صفية في حصون خيبر سنة 7 هـ لما فتحها المسلمون، فصارت في السبي لدحية الكلبي، فأخبر الصحابةُ رسولَ الله ﷺ أنها سيدة قومها ولا تصلح إلا لرسول الله إكراماً لمكانتها وتأليفاً لقلوب قومها.
فعرض النبي ﷺ عليها الإسلام فأسلمت طائعة مخلصة، فأعتقها النبي ﷺ وجعل عِتقها صداقها وتزوجها، فصارت سُنة في الفقه الإسلامي.

ثانياً: حنان النبوة وتطييب الخاطر
كان النبي ﷺ يعاملها بغاية اللطف والرحمة؛ فكان يبرك عند بعيرها ويضع ركبته الشريفة لتضع صفية رجلها على ركبته فتركب دابتها، في مشهد نبوي يأسر القلوب.
وذات يوم دخل عليها النبي ﷺ فوجدها تبكي، فسألها: «ما يبكيكِ؟»، فقالت: «بلغني أن عائشة وحفصة تقولان: نحن خير من صفية، نحن بنات عم رسول الله وأزواجه!»، فقال لها النبي ﷺ مطيباً خاطرها بحكمة بالغة: «ألا قلتِ لهن: كيف تكنّ خيراً مني وأبي هارون، وعمي موسى، وزوجي محمد؟!».

ثثالثاً: صدقها وحلمها الباهر
في مرض موت النبي ﷺ، حزنت صفية حزناً شديداً وقالت متألمة بصدق: «والله يا نبي الله، لوددتُ أن الذي بك بي!»، فغمزت أزواج النبي بأعينهن، فغضب النبي ﷺ وقال: «مضْمِضْنَ!»، قلن: «من أي شيء يا رسول الله؟»، قال: «من تغامزكن بها، والله إنها لصادقة!».
وكانت رضي الله عنها حليمة كريمة؛ سعت بها جاريتها إلى عمر بن الخطاب وقالت إنها تحب السبت وتصل اليهود، فسألها عمر فقالت: «أما السبت فلم أحبه منذ أبدلني الله به الجمعة، وأما اليهود فإن لي فيهم رحماً فأنا أصلها»، ثم اعتقت الجارية لما سألتها عما حملها على الوشاية وقالت لها: «اذهبي فأنتِ حرة لوجه الله!».

رابعاً: وفاتها
توفيت رضي الله عنها في المدينة المنورة سنة 50 هـ في خلافة معاوية بن أبي سفيان ودفنت في بقيع الغرقد مع أمهات المؤمنين.

ماذا نتعلم من سيرة صفية أم المؤمنين؟
1. الخلق النبوي الرفيع في إكرام الزوجة وتطييب خاطرها ومسح دموعها وتقدير نسبها.
2. الحلم والعفو عن المسيء ودفع السيئة بالحسنة وإعتاق الجارية التي وشت بها.
3. صلة الأرحام ولو كانوا على غير دين الإسلام ما لم يكونوا محاربين.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب النكاح، باب من جعل عتق الأمة صداقها (حديث 5086)، وكتاب الجهاد (حديث 2893).
• سنن الترمذي: كتاب المناقب، باب فضل أزواج النبي ﷺ (حديث 3892 وصححه الألباني: إنك لابنة نبي).
• سير أعلام النبلاء للذهبي، والبداية والنهاية لابن كثير (ترجمة صفية أم المؤمنين)."""
