أولاً: زواجها في عمرة القضاء
بعد صلح الحديبية بعام، خرج النبي ﷺ وأصحابه لأداء عمرة القضاء في ذي القعدة سنة 7 هـ.
ورغبت ميمونة في الزواج من النبي ﷺ والتشرف بأمومة المؤمنين، فوكلت أمرها إلى العباس بن عبد المطلب (زوج أختها أم الفضل)، فزوجها العباس للنبي ﷺ في موضع يُقال له «سَرِف» على بعد نحو عشرة أميال من مكة المكرمة بعد فراغه من العمرة، وأصدقها النبي ﷺ صداقاً شرعياً ساقه العباس.

ثانياً: شهادة عائشة بتقواها
كانت رضي الله عنها من أعبد الناس وأكثرهم ورعاً وصلة للرحم؛ وعندما توفيت قالت عنها عائشة رضي الله عنها شهادة جامعة: «ذهبت ميمونة! أما واللهِ إنها كانت من أتقانا لله، وأوصلنا للرحم!».
وروت ميمونة عن النبي ﷺ أحاديث عظيمة في الطهارة وأحكام الغسل والعبادات كان يرجع إليها كبار الصحابة للتيقن من هدي النبي في بيته.

ثالثاً: وفاتها في موضع زواجها
توفيت رضي الله عنها في خلافة معاوية بن أبي سفيان سنة 51 هـ، ومن عجائب الموافقات أنها مرضت في مكة وطلبت أن تخرج منها، فتوفيت في موضع «سَرِف» تحت الشجرة التي بنى بها النبي ﷺ فيها تماماً بعد أكثر من أربعين عاماً!
وصلى عليها ابن أختها حبر الأمة عبد الله بن عباس ونزل في قبرها وقال: «هذه زوجة نبيكم ﷺ، فإذا رفعتم جنازتها فلا تزعزعوها ولا تزلزلوها، وارفقوا بها».

ماذا نتعلم من سيرة ميمونة أم المؤمنين؟
1. صلة الرحم والتواصل الإيجابي بين الأقارب والإحسان إليهم.
2. عظمة التقوى والورع في السر والعلانية واعتراف الأقران بفضل بعضهم.
3. التمسك بالسنة النبوية وحفظ تفاصيل الطهارة وهدي البيت المحمدي.

المصادر والمراجع المعتمدة:
