أولاً: طفولتها الفدائية بمكة
نشأت في بيت النبوة تشهد الابتلاء وتشارك أباها آلام الحصار في شِعب أبي طالب.
وحين وضع عقبة بن أبي معيط سَلا الجزور وقاذوراته على ظهر النبي ﷺ وهو ساجد عند الكعبة فضحك المشركون واستهزؤوا، أقبلت فاطمة وهي صبية صغيرة تسعى باكية حتى رفعت القذى عن ظهر أبيها، ثم أقبلت على قريش في أنديتها فوبختهم بلسان شجاع لا يعرف الخوف، فاستحوا وسكتوا لهيبتها وطهارتها.

ثانياً: زواجها المبارك وبساطة العيش
تزوجها أمير المؤمنين علي بن أبي طالب في السنة الثانية للهجرة بعد غزوة بدر، وكان مهرها درعاً حطمية، وأثاث بيتها وسادة جلد حشوها ليف وجرة ماء ورحى تطحن بها.
وشكت إلى النبي ﷺ ما تلقى يداها من أثر الرحى وسألته خادماً، فأتاهما النبي ليلاً وهما في فراشهما فقال: «ألا أدلكما على خير مما سألتما؟ إذا أخذتما مضاجعكما فسبحا الله ثلاثاً وثلاثين، واحمدا ثلاثاً وثلاثين، وكبرا أربعاً وثلاثين، فهو خير لكما من خادم!»، قال علي: «فما تركتها بعد ذلك قط».
ورزقها الله الحسن والحسين سيدي شباب أهل الجنة وزينب وأم كلثوم، ومن نسلها اتصل النسل النبوي الشريف.

ثالثاً: سيدة نساء أهل الجنة وبضعة المصطفى
شهد لها النبي ﷺ بأعلى درجات الفضل؛ فقال ﷺ في الصحيحين: «فاطمة بضعة مني، فمن أغضبها أغضبني، يريبني ما رابها ويؤذيني ما آذاها»، وقال: «أفضل نساء أهل الجنة: خديجة بنت خويلد، وفاطمة بنت محمد، ومريم بنت عمران، وآسية بنت مزاحم».
وكان النبي إذا دخلت عليه قام إليها فقبلها وأجلسها في مجلسه، وإذا دخل عليها قامت إليه فقبلته وأجلسته في مجلسها.

رابعاً: سر الرحيل الأول بعد النبي
في مرض موت النبي ﷺ، دعاها فسارّها فبكت بكاءً شديداً، ثم سارّها ثانية فضحكت وتبسمت، فسألتها عائشة عن ذلك فأبت أن تفشي سر رسول الله.
فلما توفي النبي ﷺ أخبرت فاطمة بالسر وقالت: «أما حين بكيتُ فإنه أخبرني أن جبريل كان يعارضه بالقرآن في كل عام مرة وإنه عارضه العام مرتين، وما أرى ذلك إلا لاقتراب أجلي فبكيت، فلما رأى جزعي سارني فقال: ألا ترضين أن تكوني سيدة نساء أهل الجنة، وأنكِ أول أهل بيتي لحوقاً بي؟ فضحكتُ لذلك واستبشرت!».
وتوفيت رضي الله عنها بعد وفاة النبي بستة أشهر فقط في ليلة الثلاثاء 3 رمضان سنة 11 هـ وهي في ريعان شبابها وله من العمر نحو تسع وعشرين سنة، وغسلها علي وزوجها ودُفنت بالبقيع رضي الله عنها.

ماذا نتعلم من سيرة الزهراء؟
1. البر العظيم بالوالدين والوقوف معهم في أوقات المحن والابتلاء.
2. الزهد في متاع الدنيا والصبر على خشونة العيش وبساطة المهور.
3. المداومة على التسبيح والتكبير والتحميد عند النوم فهو عون عظيم للجسد والروح.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب فضائل الصحابة، باب مناقب فاطمة رضي الله عنها (حديث 3714، 3767)، وباب علامات النبوة (حديث 3623، 3624).
• صحيح مسلم: كتاب فضائل الصحابة، باب فضائل فاطمة بنت النبي ﷺ (حديث 2449، 2450).
• المستدرك للحاكم (حديث 4754: سيدة نساء أهل الجنة وصححه)."""
    },

