أولاً: بطولة الهجرة ولطمة أبي جهل
عندما أذن الله لنبيه ﷺ بالهجرة مع أبي بكر، أعدت أسماء سفرة الطعام والماء للنبي وأبيها، فلما أرادت ربط السقاء لم تجد ما تربطه به، فشقت نطاقها (حزام ثوبها) نصفين؛ فربطت بنصفه السقاء وارتدت الآخر، فقال لها النبي ﷺ مستبشراً: «أبدلكِ الله بنطاقكِ هذا نطاقين في الجنة!»، فسميت من يومها «ذات النطاقين».
وكانت تحمل الطعام سراً في عتمة الليل إلى غار ثور قاطعة الجبال الوعرة في مكة.
وجاء أبو جهل في نفر من قريش يطرق باب أبي بكر بغضب وسألها: «أين أبوكِ يا ابنة أبي بكر؟»، فقالت بشجاعة: «لا أدري أين أبي!»، فرفع أبو جهل يده ولطمها لطمة شديدة على خدها طرحت قرطها من أذنها، فثبتت كالصخرة ولم تبح بحرف واحد.

ثانياً: حيلتها الذكية مع جدها الضرير
جاء جدها أبو قحافة (وكان كفيفاً لم يسلم بعد) مشفقاً يقول: «إني لأرى أبا بكر قد فجعكم بماله مع نفسه!»، فقالت أسماء بثبات وسرعة بديهة: «كلا يا أبت! إنه قد ترك لنا خيراً كثيراً!»، ثم عمدت إلى أحجار فوضعتها في كوة البيت التي كان أبو بكر يضع فيها ماله وغطت عليها بثوب، ثم أخذت بيد جدها الكفيف وجعلته يلمس الأحجار من وراء الثوب، فقال الجد: «أما إذ ترك لكم هذا فنعم!»، فطيبت خاطره وحفظت أمانة الهجرة دون أن تكذب.

ثالثاً: شجاعتها يوم اليرموك والتربية البطولية
هاجرت إلى المدينة وهي حامل بعبد الله بن الزبير، وشهدت معركة اليرموك مع زوجها تقاتل وتحث المسلمين على الصبر وتداوي الجرحى.
وكانت رمزاً في تربية الأبناء على العزة؛ فلما دخل عليها ابنها عبد الله بن الزبير يستشيرها في مكة وهو محاصر، قالت كلمتها التاريخية التي سطرت في صحائف المجد: «يا بني، الشاة لا يضيرها سلخها بعد ذبحها! امضِ على بصيرتك ولا تمكن من عنقك غلمان بني أمية!».

رابعاً: وفاتها
عاشت رضي الله عنها مائة سنة كاملة، لم يسقط لها سن، ولم ينكر لها عقل، ولم تضعف بصيرتها، وتوفيت بمكة سنة 73 هـ بعد استشهاد ابنها عبد الله بأيام يسيرة، لتلحق بركب الصديقين والشهداء.

ماذا نتعلم من سيرة ذات النطاقين؟
1. الشجاعة النسائية الميدانية والمساهمة الفاعلة في إنجاح المهام الاستراتيجية الكبرى.
2. الثبات والصلابة في كتمان الأسرار وحماية الدعوة من مكر الأعداء.
3. عظمة التربية الإيمانية للأبناء وتقديم المبادئ وحرمات الدين على عواطف الأمومة الدنيوية.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب مناقب الأنصار، باب هجرة النبي ﷺ (حديث 3905: قصة النطاقين)، وكتاب الجهاد (حديث 2979).
• صحيح مسلم: كتاب الفضائل (حديث 2494).
• سيرة ابن هشام، وحلية الأولياء لأبي نعيم (ترجمة أسماء بنت أبي بكر)."""
