أولاً: ملحمة الفداء يوم أحد
خرجت نسيبة يوم أحد في أول النهار تسقي الجرحى وتحمل الماء، فلما انكشف المسلمون ودارت الدائرة وأحاط المشركون برسول الله ﷺ يريدون قتله، ألقت نسيبة سقاء الماء وتوشحت سيفها وأخذت ترساً، ووقفت تذود عن رسول الله ﷺ مع ثلة نادرة من أبطال الصحابة.
كانت تضرب بالسيف وترمي بالقوس وهي تحمي ظهر النبي ﷺ، حتى أصيبت يومها باثني عشر جرحاً ما بين طعنة رمح وضربة سيف، وكان أشدها جرحاً عميقاً في عاتقها ضربها به ابن قمئة المشرك.
ونظر إليها النبي ﷺ وهي تقاتل ببسالة أذهلت الرجال، فقال كلمته النبوية الخالدة: «ما التفتُّ يمنةً ولا يسرةً يوم أحد إلا وأنا أراها تقاتل دوني!».
ورأى ابنها عبد الله بن زيد جريحاً ينزف، فقالت له: «قم يا بني فضارب القوم!»، فنظر النبي ﷺ إليها وقال معجباً: «ومن يطيق ما تطيقين يا أم عمارة؟! سليني يا أم عمارة!»، فقالت بلسان الإيمان الذي لا يبتغي إلا الآخرة: «أسألك مرافقتك في الجنة!»، فقال ﷺ: «اللهم اجعلهم رفقائي في الجنة!»، فقالت مستبشرة: «ما أبالي ما أصابني من الدنيا بعد هذا!».

ثانياً: بطولتها في حروب الردة باليمامة
لم تتوقف بطولتها عند عهد النبوة؛ فعندما استشهد ابنها حبيب بن زيد صابراً قطعه مسيلمة الكذاب عضواً عضواً وهو يثبت على نبوة محمد ﷺ، أقسمت نسيبة أن تثأر لدين الله ولابنها.
فخرجت في خلافة أبي بكر الصديق مع جيش خالد بن الوليد إلى معركة اليمامة سنة 12 هـ وهي امرأة جاوزت الخمسين من عمرها، فخاضت المعركة بضراوة حتى قُطعت يدها وجُرحت أحد عشر جرحاً، ولم ترجع حتى رأت مسيلمة الكذاب صريعاً مقتولاً بحربة وحشي وسيف ابنها عبد الله بن زيد.

ثالثاً: وفاتها
عادت إلى المدينة المنورة فكان الخليفة أبو بكر الصديق يزورها في بيتها ويتفقد جراحها إجلالاً لها، وعاشت حتى توفيت في خلافة عمر بن الخطاب رضي الله عنه على الأرجح [يحتاج تحديد سنة وفاتها الدقيقة إلى تحقق يدوي لعدم ورود نص صريح في تاريخ موتها].

ماذا نتعلم من سيرة أم عمارة نسيبة بنت كعب؟
1. الشجاعة الفائقة والتضحية بالنفس دفاعاً عن الدين والقيادة عند اشتداد الكرب.
2. الهمة العالية في طلب أعلى المراتب؛ سألت مرافقة النبي ﷺ في الجنة.
3. الصبر والاحتساب العظيم عند استشهاد الأبناء والاستمرار في طريق الجهاد والعمل.

المصادر والمراجع المعتمدة:
