أولاً: إسلامها كسابقة من السابقين
كانت سمية من السابقين الأولين بمكة المكرمة؛ كانت سابع سبعة أظهروا إسلامهم في وجه طغيان قريش وتجبرها، وكانت عجوزاً ضعيفة مسنة لا ظهر لها في مكة ولا قبيلة تحميها سوى إيمانها الراسخ بربها.

ثانياً: ملحمة الصبر في رمضاء مكة
أخرجها بنو مخزوم مع زوجها ياسر وابنها عمار إلى رمضاء مكة في قيظ الظهيرة الشديد، وألبسوهم دروع الحديد وصهروهم في حرارة الشمس وأشعلوا تحتهم النيران، وكانوا يساومونها على الكفر بمحمد وسبه وعبادة اللات والعزى.
فكانت سمية العجوز الضعيفة ترفض بإباء وتكرر الشهادتين، وتتحمل آلام الحرق والضرب في صبر أذهل جلاديها.
وكان رسول الله ﷺ يمر بهم وهم يُسامون العذاب، ولا يملك من حطام الدنيا ما يدفع به عنهم، فيقول لهم بدموع الإشفاق وبشارة النبوة الصادقة: «صبراً آل ياسر.. صبراً آل ياسر، فإن موعدكم الجنة! اللهم اغفر لآل ياسر وقد فعلت!».

ثالثاً: استشهادها الخالد بأول دم في الإسلام
اشتد غيظ طاغية مكة أبي جهل (عمرو بن هشام) حين رأى انكسار كبريائه أمام ثبات هذه المرأة العجوز؛ فوقف عليها يشتمها ويهددها بالقتل إن لم تكفر بمحمد، فأغلظت له القول وأعلنت تمسكها بالإيمان واستحقارها للشرك وطغيانه، فاستشاط أبو جهل غضباً وطعنها بحربته في قبلها طعنة غادرة أودت بحياتها الطاهرة، فصعدت روحها إلى بارئها كأول شهيد وشهيدة في تاريخ هذا الدين الحنيف، وسال دمها الطاهر زكياً مسكاً يروي بطحاء مكة.
وفي يوم بدر، لما قُتل أبو جهل صريعاً في المعركة، قال النبي ﷺ لابنها عمار: «قتل اللهُ قاتلَ أمك يا عمار!».

ماذا نتعلم من سيرة أول شهيدة في الإسلام؟
1. قوة الإيمان التي تهزم جبروت الطغاة وتجعل الروح رخيصة في سبيل كلمة التوحيد.
2. أن الشهادة في سبيل الله تاج فخار لا يختص به الرجال دون النساء.
3. الصبر على أذى المشركين واليقين الجازم بأن موعد الصابرين هو الجنة.

المصادر والمراجع المعتمدة:
