أولاً: مولده الشريف بمكة
ولد القاسم بمكة المكرمة قبل بعثة النبي ﷺ ونزول الوحي، وكان أول مولود وُلد للنبي من خديجة، ففرح به النبي حباً غامراً واكتنى به، فصار يُعرف في قريش كلها بـ «أبي القاسم».
وقد نهى النبي ﷺ أمته أن يجمع أحد بعده بين اسمه وكنيته تكريماً وتوقيراً؛ فقال ﷺ في الصحيحين: «تسموا باسمي، ولا تكتنوا بكنيتي؛ فإني أنا أبو القاسم، أقسم بينكم».

ثانياً: وفاته بمكة وصبر أبويه
عاش القاسم حتى بدأ يمشي ويركب الدابة، ثم مرض وتوفي صبياً صغيراً في مكة المكرمة قبل البعثة، ودُفن في مقبرة الحجون (المعلاة).
وحزنت عليه أمه خديجة حزناً شديداً، فواساها رسول الله ﷺ وقال لها برحمة ويقين: «إن له مرضعاً في الجنة تتم رضاعه».

ماذا نتعلم من سيرة القاسم بن محمد؟
1. الصبر والاحتساب عند فقد الأولاد وفلذات الأكباد واحتساب أجرهم فرطاً في الجنة.
2. عظمة التواضع في التكني بأسماء الأبناء كما فعل سيد الخلق ﷺ.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب المناقب، باب كنية النبي ﷺ (حديث 3537).
• صحيح مسلم: كتاب الآداب، باب النهي عن التكني بأبي القاسم (حديث 2133).
• الطبقات الكبرى لابن سعد، وسيرة ابن هشام (ذكر أولاد رسول الله)."""
    },

