      "day": """هو عبد الله بن محمد بن عبد الله رسول الله ﷺ، أمه أم المؤمنين خديجة بنت خويلد رضي الله عنها، لُقب بـ «الطيب» و«الطاهر»؛ لأنه ولد في مكة بعد البعثة النبوية في ظلال الإسلام والتوحيد.

أولاً: مولده وسر تسميته بالطيب الطاهر
ولد عبد الله بمكة بعد أن شرف الله نبيه بالرسالة، وكان ولداً جميلاً طاهراً زكياً، فاستبشر به النبي وخديجة وسماه عبد الله تيمناً باسم جده وترسيخاً لمعاني العبودية لله، ولُقب بالطيب والطاهر لطهارة زمان مولده في نور الإسلام.

ثانياً: وفاته ونزول سورة الكوثر
لم يعش عبد الله طويلاً؛ فتوفي بمكة وهو طفل رضيع، ففجع به والداه صابرين محتسبين.
وانتهز طغاة قريش كالعاص بن وائل السهمي وأبي جهل هذه المصيبة، فجعلوا يشمتون بالنبي ﷺ ويقولون في أنديتهم: «انقطع ولد محمد، فهو أبتر لا يعيش له ذكر! فإذا مات انقطع ذكره واسترحتم منه!».
فحزن النبي ﷺ لشماتة أعداء الله، فأنزل الله تبارك وتعالى سورة الكوثر تسلية وتثبيتاً لنبيه، وبشارة ببقاء ذكره وخلود رسالته إلى يوم القيامة، وقطع دابر أعدائه:
﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ * فَصَلِّ لِرَبِّكَ وَانْحَرْ * إِنَّ شَانِئَكَ هُوَ الأَبْتَرُ﴾.
فكان كما أخبر القرآن؛ مات شانئو النبي وانقطع ذكرهم إلا باللعنة، وظل ذكر رسول الله ﷺ يرفع في الآفاق خمس مرات كل يوم مع كل أذان وإقامة.

ماذا نتعلم من سيرة عبد الله بن محمد؟
1. التسليم لقضاء الله عند فقد الأبناء وأن الخيرة فيما يختاره الله تبارك وتعالى.
2. أن مقاييس الشرف والخلود ليست في كثرة الذكور والجاه، بل في الإيمان والعمل الصالح والذكر الحسن.

المصادر والمراجع المعتمدة:
