      "day": """هو إبراهيم بن محمد بن عبد الله رسول الله ﷺ، أمه أم المؤمنين مارية القبطية المصرية رضي الله عنها، آخر أولاد النبي ﷺ ومولود دار الهجرة النبوية.

أولاً: مولده الشريف وفرح النبي العظيم به
ولد إبراهيم في المدينة المنورة في ذي الحجة من السنة الثامنة للهجرة في منطقة العوالي، فاستبشر به النبي ﷺ وفرح فرحاً شديداً، وقال لأصحابه في صبيحة يوم مولده: «وُلد لي الليلة غلام، فسميتُه باسم أبي إبراهيم!».
ودفعه النبي ﷺ إلى أم بردة خولة بنت المنذر ترضعه في عوالي المدينة، فكان النبي ﷺ يذهب إلى بيتها ليرى إبراهيم ويقبله ويشمه ويضمه إلى صدره الشريف.

ثانياً: وفاته ودموع الرحمة النبوية
مرض إبراهيم في شوال سنة 10 هـ وهو ابن نحو ثمانية عشر شهراً، فدخل عليه النبي ﷺ ومعه عبد الرحمن بن عوف وهو يجود بنفسه في حجر أمه، فأخذه النبي ﷺ ووضعه في حجره وذرفت عيناه الشريفتان بالدموع، فقال له عبد الرحمن بن عوف متعجباً: «وأنت يا رسول الله تبكي؟!»، فقال النبي ﷺ مبيناً ميزان الرحمة الربانية: «يا ابن عوف، إنها رحمة، ثم أتبعها بأخرى، فقال:
«إنَّ العَيْنَ تَدْمَعُ، وَالقَلْبَ يَحْزَنُ، وَلا نَقُولُ إِلَّا ما يَرْضَى رَبُّنَا، وإِنَّا بفِرَاقِكَ يا إِبْرَاهِيمُ لَمَحْزُونُونَ!».

ثالثاً: كسر خرافة الجاهلية في كسوف الشمس
من عجائب الموافقات أن الشمس كسفت كسوفاً كلياً في المدينة المنورة في نفس اليوم الذي مات فيه إبراهيم، فقال الناس والصحابة بعفوية: «إنما كسفت الشمس لموت إبراهيم ابن رسول الله!».
فلو كان النبي ﷺ مدعياً للنبوة لانتهز هذه الحادثة ليرسخ سلطانه بين الناس؛ لكنه نبي صادق مؤيد بالحق؛ فقام فصلى بالمسلمين صلاة الكسوف وأطال، ثم خطب فيهم خطبة علمية حاسمة هدم بها خرافات الأمم إلى قيام الساعة، فقال:
«إنَّ الشَّمْسَ وَالقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذلكَ، فَادْعُوا اللَّهَ، وَكَبِّرُوا، وَصَلُّوا، وَتَصَدَّقُوا!».

ماذا نتعلم من سيرة إبراهيم بن محمد؟
1. الرحمة الفطرية وحزن القلب وجريان الدمع عند المصيبة دون اعتراض أو تسخط على قضاء الله.
2. الصدق المطلق لنبوة محمد ﷺ ورفض استثمار الظواهر الكونية في بناء مجد شخصي كاذب.
3. التمسك بالسنن الشرعية كصلاة الكسوف والدعاء والصدقة عند تغير الآيات الكونية.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب الجنائز، باب قول النبي ﷺ إنا بك لمحزونون (حديث 1303)، وباب الكسوف (حديث 1040، 1043).
• صحيح مسلم: كتاب الكسوف، باب صلاة الكسوف (حديث 901، 904).
• الطبقات الكبرى لابن سعد (ذكر إبراهيم بن رسول الله)."""
