      "biography": "زينب بنت رسول الله ﷺ، أمها خديجة، تزوجت أبا العاص بن الربيع، صبرت على فراقه حتى هداه الله، وفدت زوجها بقلادة أمها خديجة، وتوفيت سنة 8 هـ.",
