      "day": """هي زينب بنت محمد رسول الله ﷺ، كبرى بناته، وأمها خديجة بنت خويلد رضي الله عنها، ولدت بمكة المكرمة قبل البعثة بعشر سنين وكان النبي ابن ثلاثين سنة.

أولاً: زواجها ووفاؤها النادر
تزوجت قبل البعثة من ابن خالتها هالة بنت خويلد: أبي العاص بن الربيع القرشي، وكان من خيرة رجال مكة تجارةً ووفاءً وأمانة.
فلما بعث النبي ﷺ أسلمت زينب، بينما ظل أبو العاص على دين قومه حياءً من قريش، وضغطت قريش عليه ليطلق ابنة محمد فرفض بإباء وشهامة قائلاً: «والله لا أفارق صاحبتي، وما أحب أن لي بامرأتي امرأة من قريش!».

ثانياً: فداء بدر وقلادة خديجة
خرج أبو العاص مكرهاً مع قريش في غزوة بدر فوقع أسيراً في أيدي المسلمين.
ولما أرسل أهل مكة أموال الفداء، أرسلت زينب في فداء زوجها قلادة ثمينة كانت أهدتها إياها أمها خديجة ليلة زفافها.
فلما رأى رسول الله ﷺ قلادة خديجة رق لها رقة شديدة واغرورقت عيناه بالدموع لذكرى خديجة ووفاء زينب، وقال لأصحابه متأدباً معهم: «إن رأيتم أن تُطلقوا لها أسيرها وتردوا عليها الذي لها فافعلوا»، فقال الصحابة بإجلال ومحبة: «نعم يا رسول الله نفديك بنفوسنا!»، فأطلقوا أبا العاص، وأخذ النبي عليه عهداً أن يخلي سبيل زينب لتهاجر إلى المدينة، فوفى أبو العاص بعهده وأرسلها.

ثالثاً: أذى الهجرة وثبات المؤمنة
في طريق هجرتها، لحق بها رجالان من مشركي قريش (هبار بن الأسود ونافع بن عبد القيس)، فنخس هبار دابتها برمح فسقطت زينب على صخرة وكانت حاملاً فأسقطت جنينها ونزفت، فدافع عنها حموها كنانة بن الربيع بنبله حتى أرجعها مكة لتتداوى، ثم خرج بها ليلاً سراً حتى بلغت المدينة المنورة.
فقال النبي ﷺ فيها متألماً لمصابها: «هي خير بناتي، أُصيبت فيّ!».

رابعاً: إسلام أبي العاص ووفاتها
في جمادى الأولى سنة 6 هـ، خرج أبو العاص في تجارة لقريش فقطع المسلمون طريقه وأخذوا أموال القافلة ففر ودخل المدينة ليلاً واستجار بزينب، فأجارته زينب ونادت بعد صلاة الفجر: «أيها الناس، إني قد أجرتُ أبا العاص بن الربيع!»، فأمضى النبي جوارها واستنقذ له أمواله كلها، فرجع إلى مكة وأدى لكل ذي حق حقه ثم قال: «يا معشر قريش، هل بقي لأحد منكم عندي مال؟»، قالوا: «لا، فجزاك الله خيراً»، فقال: «فإني أشهد أن لا إله إلا الله وأن محمداً رسول الله، والله ما منعني من الإسلام عنده إلا خوفي أن تظنوا أني أردت أكل أموالكم!».
ثم هاجر مسلماً إلى المدينة، فرد عليه النبي ﷺ زوجته زينب بنكاحها الأول إكراماً لوفائهما.
توفيت رضي الله عنها في المدينة المنورة في أوائل سنة 8 هـ متأثرة بجراح إسقاطها القديم، ونزل النبي ﷺ في قبرها ودموعه تبلل وجنتيه.

ماذا نتعلم من سيرة زينب بنت رسول الله؟
1. الوفاء الأسري بين الزوجين وتقدير المواقف النبيلة والمروءة الإنسانية.
2. جواز إجارة المرأة المسلمة للرجل واحترام القيادة والمجتمع لجوارها.
3. الصبر على الأذى في سبيل الهجرة والفرار بالدين ونيل رضوان الله.

المصادر والمراجع المعتمدة:
• سنن أبي داود: كتاب الجهاد، باب في فداء الأسير بالمال (حديث 2692: قصة قلادة خديجة).
• المستدرك على الصحيحين للحاكم (حديث 6844 وصححه الذهبي: هي خير بناتي).
• سيرة ابن هشام، والطبقات الكبرى لابن سعد (ترجمة زينب كبرى بنات النبي)."""
