      "biography": "رقية بنت رسول الله ﷺ، أمه خديجة، هاجرت الهجرتين إلى الحبشة والمدينة مع زوجها عثمان بن عفان، مرضت وماتت بالمدينة يوم قدوم بشير فتح بدر الكبرى.",
