      "day": """هي رقية بنت محمد بن عبد الله رسول الله ﷺ، أمها أم المؤمنين خديجة بنت خويلد رضي الله عنها، ولدت بمكة المكرمة والنبي ﷺ ابن ثلاث وثلاثين سنة، لُقبت بـ «ذات الهجرتين».

أولاً: هجرة الحبشة مع عثمان بن عفان
كانت رقية مخطوبة في الجاهلية لعتبة بن أبي لهب، فلما نزل الوحي بسورة المسد تبت يدا أبي لهب أمره أبوه بمفارقتها فطلقها قبل أن يدخل بها، فكان ذلك كرامة لها وصيانة لعرضها.
فتزوجها عثمان بن عفان رضي الله عنه بمكة، وكان من أجمل بيوت قريش وأنبلها.
ولما اشتد أذى قريش بالمؤمنين، أذن النبي ﷺ بالهجرة إلى الحبشة، فكان عثمان ورقية أول من خرج مهاجراً في سبيل الله فراراً بدينهما، فقال النبي ﷺ حين بلغه خروجهما: «صحبهما الله! إن عثمان لأولُ من هاجر بأهله بعد لوط عليه السلام!».
ثم رجعا إلى مكة، وهاجرا ثانية إلى المدينة المنورة، فنالت رقية شرف الهجرتين.

ثانياً: مرضها يوم بدر وموقف النبي وعثمان
في شهر رمضان من السنة الثانية للهجرة، نادى منادي الجهاد بالخروج لاعتراض عير قريش (غزوة بدر الكبرى)، وكانت رقية في المدينة تعاني من مرض الحصبة الشديد وتصارع الحمى.
فأمر النبي ﷺ زوجها عثمان بن عفان ألا يخرج مع الجيش وأن يبقى إلى جوارها في المدينة يمرضها ويرعاها، وقال له النبي مطيباً قلبه: «إن لك أجرَ رجلٍ ممن شهد بدراً وسهمه!».

ثالثاً: وفاتها وبشارة النصر
اشتد عليها المرض وتوفيت رضي الله عنها في المدينة وعثمان إلى جوارها، وبينما كان المسلمون يوارونها التراب في بقيع الغرقد، إذا بزيد بن حارثة رضي الله عنه يقبل على ناقة النبي القصواء رافعاً صوته ببشارة النصر المبين وهزيمة صناديد قريش في بدر الكبرى؛ فاختلطت دمعة فراق ابنة النبي بفرحة نصر الإسلام وظهور دينه.
ودُفنت في بقيع الغرقد، وكانت أول من دُفن فيه من بنات النبي ﷺ.

ماذا نتعلم من سيرة رقية بنت رسول الله؟
1. تقديم الواجب الإنساني والأسري في رعاية المريض والأهل على الخروج للقتال عند تكليف القيادة.
2. فضل الهجرة في سبيل الله والصبر على الغربة ومفارقة الأوطان.
3. احتساب البلاء واليقين في كرم الله بالأجر التام لمن حبسه العذر الشرعي.

المصادر والمراجع المعتمدة:
• صحيح البخاري: كتاب فضائل الصحابة، باب مناقب عثمان بن عفان (حديث 3698، 3699).
• سيرة ابن هشام: ذكر هجرة عثمان ورقية إلى الحبشة.
• الطبقات الكبرى لابن سعد، والاستيعاب لابن عبد البر (ترجمة رقية بنت رسول الله)."""
