أولاً: نشأتها وهجرتها المباركة
نشأت أم كلثوم في مكة المكرمة وتربت في حجر النبوة والخلق المحمدي السامي، وكانت مخطوبة لعتيبة بن أبي لهب ففارقها كأختها رقية صيانةً لها وكرامة.
وبقيت في مكة مع أختها فاطمة وأمها خديجة تساند أباها في سنوات الحصار والجهر بالدعوة، حتى هاجرت إلى المدينة المنورة مع أهل بيت النبي بعد استقرار دار الهجرة.

ثانياً: زواجها من عثمان ولقب ذي النورين
بعد وفاة رقية رضي الله عنها إثر غزوة بدر، حزن عثمان حزناً بالغاً لفقد رقية ولانقطاع صهره من رسول الله ﷺ، فزوجه النبي ﷺ برحمته وإكرامه ابنته أم كلثوم في ربيع الأول سنة 3 هـ صيانةً لصهره ومواساةً لقلبه.
فعاشت معه ست سنوات في مودة وسكينة وإكرام، وسُمي عثمان «ذا النورين» لأنه جمع بين ابنتي رسول الله رقية وأم كلثوم، ولم يجمع أحد بين ابنتي نبي قبله ولا بعده.

ثالثاً: وفاتها وتكفينها بإزار النبوة
مرضت رضي الله عنها وتوفيت في شعبان من السنة التاسعة للهجرة، وحزن عليها النبي ﷺ حزناً شديداً، وأمر نساء المسلمين ومنهن أم عطية الأنصارية أن يغسلنها وتراً ثلاثاً أو خمساً أو أكثر من ذلك بماء وسدر ويجعلن في الآخرة كافوراً، وأعطاهن حقوه (إزاره الشريف) تكريماً لها ليجعلنه شعارها الذي يلي جسدها.
ولما دُفنت في بقيع الغرقد، جلس رسول الله ﷺ على شفير قبرها وعيناه تذرفان دمعاً حزناً على فراقها.

ماذا نتعلم من سيرة أم كلثوم بنت رسول الله؟
1. صلة الرحم والمواساة النبوية الكريمة للأصهار الصالحين ورعاية مشاعرهم.
2. تطبيق السنة النبوية الدقيقة في غسل الميت وتكفينه وإكرامه بالدعاء عند القبر.
3. عظمة الصبر والاحتساب عند فقد البنات واحدة تلو الأخرى في حياة النبي ﷺ.

