أولاً: بشارة النبي ﷺ به
لم يلقَ أويس رسول الله ﷺ لمانع عظيم كان أحب إلى الله، وهو قيامه على خدمة أمه العجوز وبرها باليمن؛ لكن النبي ﷺ أخبر الصحابة عنه بالوحي بأدق تفاصيله؛ فقال لعمر بن الخطاب وعلي بن أبي طالب في صحيح مسلم: «يأتي عليكم أويس بن عامر مع أمداد أهل اليمن، من مراد ثم من قرن، كان به برص فبرأ منه إلا موضع درهم، له والدة هو بها برٌّ، لو أقسم على الله لأبره! فإن استطعتَ أن يستغفر لك فافعل!».

ثانياً: لقاء الفاروق عمر بأويس
ظل عمر بن الخطاب رضي الله عنه يتحرى وفود اليمن كل عام في موسم الحج ويسأل: «أفيكم أويس بن عامر؟»، حتى وافى وفد من اليمن وفيه أويس سنة 22 هـ، فأقبل عليه عمر وسأله عن صفاته فوجدها مطابقة لكلام النبي حرفياً، ورأى موضع الدرهم في جسده، فقال له عمر بإجلال: «استغفر لي!»، فاستغفر أويس لعمر وعجب الناس من طلب أمير المؤمنين الاستغفار من رجل فقير رث الثياب!
فقال له عمر: «أين تريد؟»، قال: «الكوفة»، قال: «ألا أكتب لك إلى عاملها ليكرمك؟»، فقال أويس بزهده الخالد: «أكون في غبراء الناس (عامتهم المغمورين) أحب إلي!».

ثالثاً: زهده ووفاته
عاش بالكوفة زاهداً يطعم الجياع ويصل المحتاجين، وكان إذا أمسى تصدق بما فضل من طعامه وقال: «اللهم إني أعتذر إليك من كل كبد جائعة وجسد عارٍ!».
واستشهد رضي الله عنه مجاهداً في معركة صفين سنة 37 هـ مع علي بن أبي طالب، ووُجد في جسده نيف وأربعون جراحة ما بين طعنة رمح وضربة سيف.

ماذا نتعلم من سيرة أويس القرني؟
