ثانياً: فقهه وموقفه من الخلافة
كان رأس فقهاء المدينة السبعة، وإذا جاءت المعضلات قال عمر بن عبد العزيز: «ما أقطع أمراً حتى أسمع ما يقول سعيد بن المسيب».
وضرب أروع الأمثلة في عزة العالم واستقلاليته؛ طلب منه الخليفة عبد الملك بن مروان أن يزوج ابنته لولي العهد الوليد بن عبد الملك، فرفض سعيد بكل ثبات، وزوجها لتلميذه اليتيم الفقير كثير بن أبي وداعة على مهر درهمين، وأخذ بيدها بالليل ودق بها باب تلميذه وقال له: «رأيتك أعزب فكرهت أن تبيت الليلة وحدك!».
فضُرب بالسياط مائة ضربة وأُلبس تبان صوف وطيف به في شوارع المدينة ليرضخ لبيعة وليي العهد فرفض وقال: «لا أبايع حتى يجتمع الناس!».

