أولاً: بركة النشأة في بيت النبوة
كانت أمه «خيرة» مولاة لأم المؤمنين أم سلمة، فكانت أم سلمة ترضعه من ثديها إذا غابت أمه تسكته، فدر عليه ثديها لبناً فنال بركة الرضاع من بيت النبوة.
وأتت به أمه إلى عمر بن الخطاب فمسح على رأسه وبرّك عليه ودعا له: «اللهم فقهه في الدين، وحببه إلى الناس!».

ثانياً: فصاحته وزهده ومواعظه
نشأ بالبصرة فصار إمامها ومفتيها وخطيبها؛ وكان كلامه يشبه كلام الأنبياء هيبةً ونوراً وعمقاً؛ سمعته أم المؤمنين عائشة رضي الله عنها يتكلم فقالت معجبة: «من هذا الذي يتكلم بكلام الصديقين؟!».
وكان كثير الحزن والوجل من الدار الآخرة؛ يقول أصحابه: «ما رأينا أحداً أطول حزناً من الحسن، كان كأنه رجل خرج من مقبرة أو مصيبة!».
وكان يقول كلماته الذهبية الخالدة: «يا ابن آدم، إنما أنت أيام، كلما ذهب يومٌ ذهب بعضُك!»، وقال: «هيهات! أهلك الناسَ الأماني، ليس الإيمان بالتمني ولا بالتحلي، ولكن ما وقر في القلب وصدقه العمل!».

ثالثاً: وفاته وتوقف صلاة العصر بالبصرة
توفي رضي الله عنه بالبصرة في أول رجب سنة 110 هـ وله من العمر نحو ثمان وثمانين سنة، وخرجت البصرة كلها في جنازته حتى لم تقم صلاة العصر في المسجد الجامع بالبصرة يومئذ لاشتغال الناس كلهم بتشييع جنازته، في واقعة لم تحدث في تاريخ البصرة قط.

ماذا نتعلم من سيرة الحسن البصري؟
1. تدبر حقيقة الدنيا وسرعة فنائها واستثمار الأيام والأنفاس في العمل الصالح.
2. صدق الموعظة وأثر خروج الكلمة من القلب الصادق في إحياء قلوب السامعين.
