      "day": """هو علي بن الحسين بن علي بن أبي طالب الهاشمي القرشي، كنيته «أبو الحسن» و«أبو محمد»، لُقب بـ «زين العابدين» لعبادته الغامرة، وبـ «السجّاد» لكثرة سجوده وبكائه في جوف الليل.

أولاً: محنة كربلاء وثبات الإيمان
ولد في المدينة المنورة سنة 38 هـ، وشهد مأساة كربلاء سنة 61 هـ مع والده الشهيد الحسين بن علي، وكان علي بن الحسين مريضاً بالحمى لا يقوى على القتال، فنجاه الله من القتل، فحمل بعد ذلك أمانة آل البيت النبوي بحكمة بالغة وحلم وزهد وصبر عظيم، ممتنعاً عن الخوض في الصراعات السياسية.

ثانياً: صدقة السر العظيمة التي لا يعلمها أحد
كان رضي الله عنه إماماً في العطاء الخفي؛ كان يخرج في سواد الليل متلثماً يحمل جراب الخبز والدقيق على ظهره، ويطوف ببيوت فقراء المدينة وأراملها فيطرق أبوابهم ويضع الطعام وينصرف دون أن يعلموا من هو!
وكان يعول مائة بيت في المدينة لا يدرون من ينفق عليهم، فلما مات رضي الله عنه سنة 94 هـ انقطع عنهم ذلك الطعام، فلما جردوه للغسل رأوا في ظهره ورقبته آثاراً سوداء كركب الإبل من ثقل الأحمال التي كان ينقلها للمحتاجين بالليل!

ثالثاً: حلمه وعفوه المذهل
سبّه رجل يوماً في وجهه وأسمعه المكروه، فما رد عليه حتى فرغ، ثم قال له برفق: «يا أخي، إن كنا كما قلت فنستغفر الله، وإن لم نكن كما قلت فغفر الله لك!»، فقام الرجل خجلاً وقبل رأسه وقال: «أشهد أنك ابن رسول الله حقاً!».
وكان إذا توضأ للصلاة اصفر وجهه وارتعدت فرائصه، فإذا سُئل قال: «أتدرون بين يدي من أريد أن أقوم ومن أناجي؟!».

رابعاً: وفاته بالمدينة
توفي في المدينة المنورة سنة 94 هـ ودُفن في بقيع الغرقد إلى جانب عمه الإمام الحسن بن علي رضي الله عنهما.

ماذا نتعلم من سيرة زين العابدين؟
1. فضل صدقة السر وكتمان الإحسان ليكون خالصاً لوجه الله تعالى بعيداً عن الرياء.
2. الخشوع والهيبة عند الوقوف للصلاة ومناجاة رب العالمين.
3. الحلم العظيم والعفو عن المسيء وكظم الغيظ دفعاً بالتي هي أحسن.

المصادر والمراجع المعتمدة:
• حلية الأولياء لأبي نعيم (ترجمة علي بن الحسين زين العابدين).
• سير أعلام النبلاء للذهبي (الجزء الرابع).
• الطبقات الكبرى لابن سعد، وصفة الصفوة لابن الجوزي."""
    },

    "عمر بن عبد العزيز": {
      "description": "خامس الخلفاء الراشدين، الإمام العادل المجدد، الذي ملأ الأرض قسطاً بعد أن ملئت جوراً.",
      "biography": "عمر بن عبد العزيز بن مروان الأموي القرشي، أبو حفص، حفيد عمر بن الخطاب لأمه، تولى الخلافة سنتين وخمسة أشهر فرد المظالم وأغنى الناس حتى لم يجدوا من يقبل الصدقة.",
      "battles": [],
      "attributes": ["الخليفة العادل","خامس الخلفاء الراشدين","المجدد الأول","حفيد الفاروق"],
      "additionalInfo": "كانت أمه أم عاصم بنت عاصم بن عمر بن الخطاب، فتحققت فيه فراسة جده الفاروق.",
      "day": """هو عمر بن عبد العزيز بن مروان بن الحكم الأموي القرشي، كنيته «أبو حفص»، أمه ليلى أم عاصم بنت عاصم بن عمر بن الخطاب، لُقب بـ «الخليفة الصالح» و«خامس الخلفاء الراشدين» لعدله وسيره بسيرة الخلفاء الراشدين، والمجدد الأول لأمر الدين على رأس المائة الأولى.

أولاً: نشأته وبركته
ولد بالمدينة المنورة وتأدب على يد فقهائها كالصحابي عبد الله بن عمر وسعيد بن المسيب، وكان شبيهاً بجده عمر بن الخطاب في خلقه وعدله؛ وكان يُلقب بـ «أشج بني أمية» لشجة أصابته في وجهه من رمحة دابة وهو غلام، فكان أهله يستبشرون بصلاحه وسيره على نهج جده الفاروق.

ثانياً: زلزلة الخلافة ورد المظالم
تولى الخلافة سنة 99 هـ بعد سليمان بن عبد الملك على غير رغبة منه، فبكى بكاءً مراً وصعد المنبر وقال: «أيها الناس، إني قد ابتُليتُ بهذا الأمر من غير رأي مني ولا طلبة ولا مشورة من المسلمين، وإني قد خلعتُ ما في أعناقكم من بيعتي، فاختاروا لأنفسكم!»، فصاح الناس بصوت واحد: «قد اخترناك ورضينا بك يا أمير المؤمنين!».
فبدأ بنفسه وأهل بيته فوراً؛ فرد كل أموال بني أمية وضياعهم إلى بيت مال المسلمين، وجرد نفسه وزوجته فاطمة بنت عبد الملك من حليها وجواهرها وردها لبيت المال، ولبس الثوب الخشن المرقع بعد أن كان أنعم شباب قريش.

ثالثاً: العدل المطلق والرخاء الشامل
أوقف الحروب وركز على نشر الدعوة بالعدل والإحسان، ورفع الجزية عمن أسلم وقال لمن عارضه: «إن الله بعث محمداً هادياً ولم يبعثه جابياً!».
وضرب العدل في عهده آفاق الأرض في ثلاثين شهراً فقط؛ حتى فاض المال في بيت المال، وأمر مناديه في الأسواق: «أين الغارمون؟ أين الناكحون؟ أين الفقراء؟»، فكان يقضى دين المدينين ويزوج الشباب من بيت المال، حتى طاف عمال الزكاة بالصدقات في إفريقيا والشام والعراق فما وجدوا رجلاً فقيراً واحداً يقبل الصدقة لغنى الناس وكفايتهم!

رابعاً: وفاته رضي الله عنه
دس له بعض بني أمية السم في طعامه بعد أن ضاقوا ذرعاً بعدله وتجريده لأموالهم غير المشروعة، فعلم بالسم وعفا عن خادمه وأعتقه، وتوفي بدير سمعان بالشام في رجب سنة 101 هـ وله من العمر نحو تسع وثلاثين سنة، ودُفن هناك وحزنت الأمة عليه حزناً غامراً.

ماذا نتعلم من سيرة عمر بن عبد العزيز؟
1. أن العدل ومحاربة الفساد كفيلان بنشر الرخاء والقضاء على الفقر في أقصر مدة.
2. الزهد في بريق السلطة والبدء بالنفس والقرابة في تطبيق معايير النزاهة.
3. التواضع وتقديم الرحمة على الجباية والسعي لهداية الناس وكفايتهم.

المصادر والمراجع المعتمدة:
• سيرة عمر بن عبد العزيز لابن عبد الحكم (أقدم كتاب في سيرته).
• حلية الأولياء لأبي نعيم، وسير أعلام النبلاء للذهبي (الجزء الخامس).
• البداية والنهاية لابن كثير (أحداث خلافة ووفاة عمر بن عبد العزيز)."""
    }
